s.includes('*');\\n}\\n\\nreturn [{\\n  json: {\\n    ...input,\\n    isAdmin,\\n    scopes,\\n    clientId: result.client_id || null\\n  }\\n}];"},"id":"verify-admin","name":"Verify Admin","type":"n8n-nodes-base.code","typeVersion":2,"position":[750,0]},{"parameters":{"conditions":{"boolean":[{"value1":"={{$json.isAdmin}}","operation":"isTrue"}]}},"id":"is-admin-check","name":"Is Admin?","type":"n8n-nodes-base.if","typeVersion":2,"position":[1000,0]},{"parameters":{"operation":"executeQuery","query":"SELECT \\n  id,\\n  conversation_key,\\n  msg_id,\\n  channel,\\n  payload_json,\\n  error_message,\\n  retry_count\\nFROM outbound_messages\\nWHERE status = 'DLQ'\\n  AND ($1::text[] IS NULL OR msg_id = ANY($1::text[]))\\n  AND ($2::text = '' OR channel = $2::text)\\nORDER BY created_at ASC\\nLIMIT $3;","additionalFields":{"queryParams":"={{[$json.options.msgIds.length > 0 ? $json.options.msgIds : null, $json.options.channel, $json.options.maxMessages]}}"}},"id":"fetch-dlq-for-replay","name":"Fetch DLQ Messages","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[1250,-100],"credentials":{"postgres":{"id":"POSTGRES_CREDENTIAL_ID","name":"Postgres"}}},{"parameters":{"language":"javascript","jsCode":"const messages = $input.all();\\nconst input = $('Verify Admin').first().json;\\nconst isDryRun = input.options?.dryRun === true;\\n\\nif (messages.length === 0) {\\n  return [{\\n    json: {\\n      success: true,\\n      replayed: 0,\\n      message: 'No DLQ messages found matching criteria',\\n      dryRun: isDryRun\\n    }\\n  }];\\n}\\n\\n// Prepare messages for replay\\nconst toReplay = messages.map(m => ({\\n  id: m.json.id,\\n  msg_id: m.json.msg_id,\\n  channel: m.json.channel,\\n  payload: m.json.payload_json,\\n  previousError: m.json.error_message,\\n  retryCount: m.json.retry_count\\n}));\\n\\nreturn [{\\n  json: {\\n    toReplay,\\n    count: toReplay.length,\\n    dryRun: isDryRun,\\n    options: input.options\\n  }\\n}];"},"id":"prepare-replay","nam