rsion":2,"position":[780,60]},{"parameters":{"conditions":{"string":[{"value1":"={{$json._op}}","operation":"equal","value2":"LIST"}]}},"id":"if_list","name":"Z2 - Is LIST?","type":"n8n-nodes-base.if","typeVersion":2,"position":[980,60]},{"parameters":{"conditions":{"string":[{"value1":"={{$json._op}}","operation":"equal","value2":"DELETE"}]}},"id":"if_del","name":"Z3 - Is DELETE?","type":"n8n-nodes-base.if","typeVersion":2,"position":[980,200]},{"parameters":{"operation":"executeQuery","query":"SELECT zone_id, wilaya, commune, fee_base_cents, min_order_cents, eta_min, eta_max, is_active, created_at, updated_at\\nFROM public.delivery_zones\\nWHERE restaurant_id = $1\\nORDER BY lower(wilaya), lower(commune);","additionalFields":{"queryParams":"={{[$json.restaurantId]}}"}},"id":"db_list_zones","name":"Z4 - List Zones (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[1200,60]},{"parameters":{"operation":"executeQuery","query":"DELETE FROM public.delivery_zones\\nWHERE restaurant_id = $1 AND zone_id = $2\\nRETURNING zone_id;","additionalFields":{"queryParams":"={{[$json.restaurantId, $json.zone_id]}}"}},"id":"db_del_zones","name":"Z5 - Delete Zone (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[1200,200]},{"parameters":{"operation":"executeQuery","query":"WITH inp AS (\\n  SELECT\\n    $1::uuid AS restaurant_id,\\n    NULLIF(trim($2::text),'') AS wilaya,\\n    NULLIF(trim($3::text),'') AS commune,\\n    GREATEST(COALESCE($4::int,0),0) AS fee_base_cents,\\n    GREATEST(COALESCE($5::int,0),0) AS min_order_cents,\\n    GREATEST(COALESCE($6::int,0),0) AS eta_min,\\n    GREATEST(COALESCE($7::int,0),0) AS eta_max,\\n    COALESCE($8::boolean,true) AS is_active\\n), u AS (\\n  UPDATE public.delivery_zones z\\n  SET fee_base_cents=inp.fee_base_cents,\\n      min_order_cents=inp.min_order_cents,\\n      eta_min=inp.eta_min,\\n      eta_max=GREATEST(inp.eta_max, inp.eta_min),\\n      is_active=inp.is_active,\\n      updated_at=now()\\n  FROM inp\\n  WHERE z.restaurant_id=inp.restaurant_id\\n    AND lower(z.wilaya)=lower(inp.wilaya)\\n    AND lower(z.commune)=lower(inp.commune)\\n  RETURNING z.zone_id\\n), i AS (\\n  INSERT INTO public.delivery_zones(restaurant_id,wilaya,commune,fee_base_cents,min_order_cents,eta_min,eta_max,is_active)\\n  SELECT inp.restaurant_id, inp.wilaya, inp.commune, inp.fee_base_cents, inp.min_order_cents, inp.eta_min, GREATEST(inp.eta_max, inp.eta_min), inp.is_active\\n  FROM inp\\n  WHERE inp.wilaya IS NOT NULL AND inp.commune IS NOT NULL\\n    AND NOT EXISTS (SELECT 1 FROM u)\\n  RETURNING zone_id\\n)\\nSELECT COALESCE((SELECT zone_id FROM u), (SELECT zone_id FROM i)) AS zone_id;","additionalFields":{"queryParams":"={{[$json.restaurantId, $json.zone.wilaya, $json.zone.commune, $json.zone.fee_base_cents, $json.zone.min_order_cents, $json.zone.eta_min, $json.zone.eta_max, $json.zone.is_active]}}"}},"id":"db_upsert_zone","name":"Z6 - Upsert Zone (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[1200,340]}]	{"B0 - Parse Auth":{"main":[[{"node":"B0 - Resolve Client (DB)","type":"main","index":0}]]},"B0 - Resolve Client (DB)":{"main":[[{"node":"B0 - Apply Auth Context","type":"main","index":0}]]},"B0 - Apply Auth Context":{"main":[[{"node":"B0 - Access OK?","type":"main","index":0}]]},"B0 - Access OK?":{"main":[[{"node":"Z1 - Route Operation","type":"main","index":0}],[{"node":"B0 - Log Deny (DB)","type":"main","index":0}]]},"B0 - Log Allow (Audit)":{"main":[[{"node":"RESP - 200 OK","type":"main","index":0}]]},"B0 - Log Deny (DB)":{"main":[[{"node":"RESP - 403 Forbidden","type":"main","index":0}]]},"IN - Webhook GET":{"main":[[{"node":"A0 - Mark GET","type":"main","index":0}]]},"A0 - Mark GET":{"main":[[{"node":"B0 - Parse Auth","type":"main","index":0}]]},"IN - Webhook POST":{"main":[[{"node":"A0 - Mark POST","type":"main","index":0}]]},"A0 - Mark POST":{"main":[[{"node":"B0 - Parse Auth","type":"main","index":0}]]},"Z1 - Route Operation":{"main":[[{"node":"Z2 - Is LIS