W8 - DLQ Handler (Dead Letter Queue)	t	[{"parameters":{"rule":{"interval":[{"field":"minutes","minutesInterval":5}]}},"id":"schedule-trigger","name":"Every 5 Minutes","type":"n8n-nodes-base.scheduleTrigger","typeVersion":1.1,"position":[0,0]},{"parameters":{"operation":"executeQuery","query":"SELECT \\n  id,\\n  conversation_key,\\n  msg_id,\\n  channel,\\n  payload_json,\\n  error_message,\\n  retry_count,\\n  created_at,\\n  last_retry_at\\nFROM outbound_messages\\nWHERE status = 'DLQ'\\n  AND (last_retry_at IS NULL OR last_retry_at < NOW() - INTERVAL '1 hour')\\nORDER BY created_at ASC\\nLIMIT 50;"},"id":"fetch-dlq-messages","name":"Fetch DLQ Messages","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[250,0],"credentials":{"postgres":{"id":"POSTGRES_CREDENTIAL_ID","name":"Postgres"}}},{"parameters":{"language":"javascript","jsCode":"const messages = $input.all();\\nconst dlqCount = messages.length;\\n\\n// Check alert threshold\\nconst alertThreshold = Number($env.DLQ_ALERT_THRESHOLD || 10);\\nconst shouldAlert = dlqCount >= alertThreshold;\\n\\n// Log DLQ status\\nconst summary = {\\n  dlqCount,\\n  alertThreshold,\\n  shouldAlert,\\n  checkedAt: new Date().toISOString(),\\n  messages: messages.map(m => ({\\n    id: m.json.id,\\n    channel: m.json.channel,\\n    msg_id: m.json.msg_id,\\n    error: m.json.error_message,\\n    retries: m.json.retry_count,\\n    age: m.json.created_at\\n  }))\\n};\\n\\nreturn [{ json: summary }];"},"id":"analyze-dlq","name":"Analyze DLQ","type":"n8n-nodes-base.code","typeVersion":2,"position":[500,0]},{"parameters":{"conditions":{"boolean":[{"value1":"={{$json.shouldAlert}}","operation":"isTrue"}]}},"id":"should-alert-check","name":"Should Alert?","type":"n8n-nodes-base.if","typeVersion":2,"position":[750,0]},{"parameters":{"operation":"executeQuery","query":"INSERT INTO security_events (\\n  event_type,\\n  severity,\\n  payload_json\\n) VALUES (\\n  'DLQ_THRESHOLD_EXCEEDED',\\n  'HIGH',\\n  $1::jsonb\\n);","additional