,"position":[700,300],"id":"889ffb18-4e9d-452f-882f-d84de8f1db7f"},{"parameters":{"url":"={{ $env.WA_SEND_URL || `https://graph.facebook.com/${$env.GRAPH_API_VERSION || 'v21.0'}/${$env.WA_PHONE_NUMBER_ID}/messages` }}","method":"POST","sendBody":true,"bodyParameters":{"parameters":[{"name":"messaging_product","value":"whatsapp"},{"name":"to","value":"={{ $json.phone }}"},{"name":"type","value":"text"},{"name":"text","value":"={{ { body: $json.messageText } }}"}]},"headerParameters":{"parameters":[{"name":"Authorization","value":"Bearer {{ $env.WA_API_TOKEN }}"}]}},"name":"Send History","type":"n8n-nodes-base.httpRequest","typeVersion":3,"position":[900,300],"id":"b1e211dd-a3d7-4006-aca5-5d60dd036553"}]	{"History Request":{"main":[[{"node":"Parse Phone","type":"main","index":0}]]},"Parse Phone":{"main":[[{"node":"Fetch History","type":"main","index":0}]]},"Fetch History":{"main":[[{"node":"Format History","type":"main","index":0}]]},"Format History":{"main":[[{"node":"Send History","type":"main","index":0}]]}}	2026-02-22 20:56:05.016+00	2026-02-22 20:56:05.016+00	\N	\N	\N	10e53c0c-f6ab-4460-aff4-9cf2cf6b9bdd	1	iNmoGNa1wJKdlHkE	\N	\N	f	4	\N	\N
W_PAYMENT_CALLBACK	t	[{"parameters":{"httpMethod":"POST","path":"chargily-callback","options":{}},"name":"Chargily Webhook","type":"n8n-nodes-base.webhook","typeVersion":1,"position":[100,300],"id":"23686d56-caf3-44ab-b2d6-960d1274edb6"},{"parameters":{"jsCode":"// Verify Chargily signature\\nconst crypto = require('crypto');\\nconst signature = $input.first().headers['signature'] || '';\\nconst payload = JSON.stringify($input.first().json);\\nconst secret = $env.CHARGILY_SECRET_KEY;\\n\\nconst expectedSignature = crypto\\n  .createHmac('sha256', secret)\\n  .update(payload)\\n  .digest('hex');\\n\\nconst isValid = signature === expectedSignature;\\nconst event = $input.first().json;\\n\\nreturn {\\n  json: {\\n    is_valid: isValid,\\n    event_type: event.type,\\n    checkout_id: event.data?.id,\\n    order_id: event.data?.metadata?.order_id,\\n    status: event.data?.status\\n  }\\n};"},"name":"Verify Signature","type":"n8n-nodes-base.code","typeVersion":1,"position":[300,300],"id":"5315a296-c1c1-4abe-be22-90270021df5b"},{"parameters":{"conditions":{"boolean":[{"value1":"={{ $json.is_valid }}","operation":"equal","value2":"={{ true }}"}]}},"name":"Valid Signature?","type":"n8n-nodes-base.if","typeVersion":1,"position":[500,300],"id":"7b66768e-23ba-4d26-8d87-a7e370432cc2"},{"parameters":{"conditions":{"string":[{"value1":"={{ $json.status }}","operation":"equal","value2":"paid"}]}},"name":"Is Paid?","type":"n8n-nodes-base.if","typeVersion":1,"position":[700,200],"id":"ba3ebb24-afc1-4068-9f77-a25ced6c029d"},{"parameters":{"operation":"update","collection":"payments","filters":{"external_id":"={{ $json.checkout_id }}"},"fields":{"status":"paid","paid_at":"={{ new Date().toISOString() }}"}},"name":"Mark Payment Paid","type":"n8n-nodes-base.strapi","typeVersion":1,"position":[900,100],"id":"a45a8fdc-d10e-4a5e-a6bb-03e82f948b17"},{"parameters":{"operation":"update","collection":"orders","id":"={{ $json.order_id }}","fields":{"payment_status":"paid","status":"confirmed"}},"name":"Confirm Order","type":"n8n-nodes-base.strapi","typeVersion":1,"position":[1100,100],"id":"57c7a3a2-bc9a-448d-b90c-cb571425e954"}]	{"Chargily Webhook":{"main":[[{"node":"Verify Signature","type":"main","index":0}]]},"Verify Signature":{"main":[[{"node":"Valid Signature?","type":"main","index":0}]]},"Valid Signature?":{"main":[[{"node":"Is Paid?","type":"main","index":0}],[]]},"Is Paid?":{"main":[[{"node":"Mark Payment Paid","type":"main","index":0}],[]]},"Mark Payment Paid":{"main":[[{"node":"Confirm Order","type":"main","index":0}]]}}	2026-02-22 20:56:05.016+00	2026-02-22 20:56:05.016+00	\N	\N	\N	7e0aeabc-a6f4-4b44-8815-793a7f01318d	1	8tSM1gTQ19RIFpDC	\N	\N	f	4	\N	\N
W17 - Health Monitor (Alert on Failure)	t	[{"parameters":{"rule":{"interval":[{"field":"minutes","minutesInterval":1}]}},"id":"health-monitor-cron","name":"CRON - Every 1min","type":"n8n-nodes-base.scheduleTrigger","typeVersion":1,"position":[-800,0]},{"parameters":{"language":"javascript","jsCode":"/**\\n * P1-05: Health Monitor - Check if enabled\\n */\\nconst monitorEnabled = (($env.HEALTH_MONITOR_ENABLED || 'true').toString().toLowerCase() !== 'false');\\nconst alertThreshold = parseInt($env.HEALTH_ALERT_THRESHOLD || '3', 10);\\nconst alertCooldownSec = parseInt($env.ALERT_COOLDOWN_SEC || '300', 10);\\nconst webhookBaseUrl = ($env.WEBHOOK_URL || 'http://localhost:5678').toString().trim();\\n\\nif (!monitorEnabled) {\\n  return [{ json: { skip: true, reason: 'MONITOR_DISABLED' } }];\\n}\\n\\nreturn [{\\n  json: {\\n    skip: false,\\n    config: {\\n      alertThreshold,\\n      alertCooldownSec,\\n      webhookBaseUrl,\\n      readyzUrl: `${webhookBaseUrl}/webhook/readyz`,\\n      timestamp: new Date().toISOString()\\n    }\\n  }\\n}];\\n"},"id":"monitor-config","name":"B0 - Config","type":"n8n-nodes-base.code","typeVersion":2,"position":[-550,0]},{"parameters":{"conditions":{"boolean":[{"value1":"={{$json.skip}}","operation":"isFalse"}]}},"id":"monitor-enabled-check","name":"B0 - Enabled?","type":"n8n-nodes-base.if","typeVersion":2,"position":[-300,0]},{"parameters":{"operation":"get","key":"ralphe:health:fail_count"},"id":"get-fail-count","name":"B1 - Get Fail Count","type":"n8n-nodes-base.redis","typeVersion":1,"position":[-50,-100],"credentials":{"redis":{"id":"REDIS_CREDENTIAL_ID","name":"Redis"}},"continueOnFail":true},{"parameters":{"language":"javascript","jsCode":"/**\\n * P1-05: Parse current fail count and call readyz\\n */\\nconst config = $('B0 - Config').first().json.config;\\nconst redisResult = $json;\\n\\nlet currentFailCount = 0;\\nif (redisResult && typeof redisResult === 'string' && !isNaN(parseInt(redisResult))) {\\n  currentFailCount = parseInt(redisResult);\\n} else if (typeof redisResult === 'number') {\\n  currentFailCount = redisResult;\\n}\\n\\nreturn [{\\n  json: {\\n    config,\\n    currentFailCount,\\n    readyzUrl: config.readyzUrl\\n  }\\n}];\\n"},"id":"parse-fail-count","name":"B1 - Parse Fail Count","type":"n8n-nodes-base.code","typeVersion":2,"position":[200,-100]},{"parameters":{"language":"javascript","jsCode":"/**\\n * P1-05: Call readyz endpoint to check health\\n */\\nconst input = $json;\\nconst config = input.config;\\nconst readyzUrl = input.readyzUrl;\\n\\nlet healthOk = false;\\nlet healthResponse = null;\\nlet healthError = null;\\n\\ntry {\\n  const response = await $httpRequest({\\n    method: 'GET',\\n    url: readyzUrl,\\n    timeout: 10000,\\n    returnFullResponse: true\\n  });\\n  \\n  const statusCode = response.statusCode || response.status || 500;\\n  healthResponse = response.body || response.data;\\n  \\n  if (statusCode >= 200 && statusCode < 300) {\\n    healthOk = true;\\n  } else {\\n    healthError = `HTTP ${statusCode}`;\\n  }\\n} catch (err) {\\n  healthError = err.message || 'Request failed';\\n}\\n\\nreturn [{\\n  json: {\\n    ...input,\\n    healthOk,\\n    healthResponse,\\n    healthError,\\n    checkedAt: new Date().toISOString()\\n  }\\n}];\\n"},"id":"call-readyz","name":"B2 - Call Readyz","type":"n8n-nodes-base.code","typeVersion":2,"position":[450,-100]},{"parameters":{"conditions":{"boolean":[{"value1":"={{$json.healthOk}}","operation":"isTrue"}]}},"id":"health-ok-check","name":"B2 - Health OK?","type":"n8n-nodes-base.if","typeVersion":2,"position":[700,-100]},{"parameters":{"operation":"set","key":"ralphe:health:fail_count","value":"0","expire":true,"ttl":3600},"id":"reset-fail-count","name":"B3 - Reset Fail Count","type":"n8n-nodes-base.redis","typeVersion":1,"position":[950,-200],"credentials":{"redis":{"id":"REDIS_CREDENTIAL_ID","name":"Redis"}},"continueOnFail":true},{"parameters":{"language":"javascript","jsCode":"/**\\n * P1-05: Increment fail count and check if should alert\\n */\\nconst input = $json;\\nconst config = input.config;\\nconst currentFailCount = input.currentFailCount || 0;\\nconst newFailCount = currentFailCount + 1;\\nconst alertThreshold = config?.alertThreshold || 3;\\n\\nconst shouldAlert = newFailCount >= alertThreshold;\\n\\nreturn [{\\n  json: {\\n    ...input,\\n    newFailCount,\\n    shouldAlert,\\n    alertThreshold\\n  }\\n}];\\n"},"id":"increment-fail-count","name":"B3 - Increment Fail Count","type":"n8n-nodes-base.code","typeVersion":2,"position":[950,0]},{"parameters":{"operation":"set","key":"ralphe:health:fail_count","value":"={{$json.newFailCount.toString()}}","expire":true,"ttl":3600},"id":"store-fail-count","name":"B3 - Store Fail Count","type":"n8n-nodes-base.redis","typeVersion":1,"position":[1200,0],"credentials":{"redis":{"id":"REDIS_CREDENTIAL_ID","name":"Redis"}},"continueOnFail":true},{"parameters":{"conditions":{"boolean":[{"value1":"={{$json.shouldAlert}}","operation":"isTrue"}]}},"id":"should-alert-check","name":"B4 - Should Alert?","type":"n8n-nodes-base.if","typeVersion":2,"position":[1450,0]},{"parameters":{"operation":"get","key":"ralphe:health:last_alert"},"id":"get-last-alert","name":"B4 - Get Last Alert","type":"n8n-nodes-base.redis","typeVersion":1,"position":[1700,-100],"credentials":{"redis":{"id":"REDIS_CREDENTIAL_ID","name":"Redis"}},"continueOnFail":true},{"parameters":{"language":"javascript","jsCode":"/**\\n * P1-05: Check alert cooldown\\n */\\nconst input = $('B3 - Store Fail Count').first().json;\\nconst lastAlertResult = $json;\\nconst config = input.config;\\nconst cooldownSec = config?.alertCooldownSec || 300;\\n\\nlet lastAlertTime = 0;\\nif (lastAlertResult && typeof lastAlertResult === 'string' && !isNaN(parseInt(lastAlertResult))) {\\n  lastAlertTime = parseInt(lastAlertResult);\\n}\\n\\nconst now = Date.now();\\nconst timeSinceLastAlert = now - lastAlertTime;\\nconst cooldownMs = cooldownSec * 1000;\\n\\nconst canAlert = timeSinceLastAlert >= cooldownMs;\\n\\nreturn [{\\n  json: {\\n    ...input,\\n    canAlert,\\n    lastAlertTime,\\n    cooldownSec,\\n    timeSinceLastAlert: Math.round(timeSinceLastAlert / 1000)\\n  }\\n}];\\n"},"id":"check-cooldown","name":"B4 - Check Cooldown","type":"n8n-nodes-base.code","typeVersion":2,"position":[1950,-100]},{"parameters":{"conditions":{"boolean":[{"value1":"={{$json.canAlert}}","operation":"isTrue"}]}},"id":"can-alert-check","name":"B4 - Can Alert?","type":"n8n-nodes-base.if","typeVersion":2,"position":[2200,-100]},{"parameters":{"language":"javascript","jsCode":"/**\\n * P1-05: Prepare alert message for admin\\n */\\nconst input = $json;\\nconst adminPhone = ($env.ADMIN_ALERT_PHONE || '').toString().trim();\\nconst alertWebhook = ($env.ALERT_WEBHOOK_URL || '').toString().trim();\\n\\nif (!adminPhone && !alertWebhook) {\\n  return [{ json: { ...input, alertSkipped: true, reason: 'NO_ALERT_TARGET' } }];\\n}\\n\\nconst failedChecks = [];\\nif (input.healthResponse?.checks) {\\n  for (const [name, check] of Object.entries(input.healthResponse.checks)) {\\n    if (check.status !== 'ok') {\\n      failedChecks.push(`${name}: ${check.error || 'FAIL'}`);\\n    }\\n  }\\n}\\n\\nconst alertMessage = `🚨 ALERTE SANTÉ SYSTÈME\\\\n\\\\nStatut: ${input.healthResponse?.status || 'UNKNOWN'}\\\\nÉchecs consécutifs: ${input.newFailCount}\\\\nProblèmes: ${failedChecks.length > 0 ? failedChecks.join(', ') : input.healthError || 'Unknown'}\\\\n\\\\nHeure: ${input.checkedAt}`;\\n\\nreturn [{\\n  json: {\\n    ...input,\\n    adminPhone,\\n    alertWebhook,\\n    alertMessage,\\n    failedChecks\\n  }\\n}];\\n"},"id":"prepare-alert","name":"B5 - Prepare Alert","type":"n8n-nodes-base.code","typeVersion":2,"position":[2450,-200]},{"parameters":{"operation":"set","key":"ralphe:health:last_alert","value":"={{Date.now().toString()}}","expire":true,"ttl":86400},"id":"set-last-alert","name":"B5 - Set Last Alert","type":"n8n-nodes-base.redis","typeVersion":1,"position":[2700,-200],"credentials":{"redis":{"id":"REDIS_CREDENTIAL_ID","name":"Redis"}},"continueOnFail":true},{"parameters":{"language":"javascript","jsCode":"/**\\n * P1-05: Send alert via WhatsApp (if configured) or webhook\\n */\\nconst input = $json;\\nconst adminPhone = input.adminPhone;\\nconst alertWebhook = input.alertWebhook;\\nconst alertMessage = input.alertMessage;\\n\\nlet alertSent = false;\\nlet alertError = null;\\n\\n// Try webhook first (generic, could be Slack, Discord, etc.)\\nif (alertWebhook) {\\n  try {\\n    await $httpRequest({\\n      method: 'POST',\\n      url: alertWebhook,\\n      body: {\\n        text: alertMessage,\\n        type: 'health_alert',\\n        severity: 'critical',\\n        timestamp: new Date().toISOString()\\n      },\\n      json: true,\\n      timeout: 10000\\n    });\\n    alertSent = true;\\n  } catch (err) {\\n    alertError = err.message;\\n  }\\n}\\n\\n// If webhook failed or not configured, try WhatsApp\\nif (!alertSent && adminPhone) {\\n  const waUrl = $env.WA_SEND_URL;\\n  const waToken = $env.WA_API_TOKEN;\\n  const waPhoneId = $env.WA_PHONE_NUMBER_ID;\\n  const graphVersion = $env.GRAPH_API_VERSION || 'v21.0';\\n  \\n  let sendUrl = waUrl;\\n  if (!sendUrl && waPhoneId) {\\n    sendUrl = `https://graph.facebook.com/${graphVersion}/${waPhoneId}/messages`;\\n  }\\n  \\n  if (sendUrl && waToken) {\\n    try {\\n      await $httpRequest({\\n        method: 'POST',\\n        url: sendUrl,\\n        headers: {\\n          'Authorization': `Bearer ${waToken}`,\\n          'Content-Type': 'application/json'\\n        },\\n        body: {\\n          messaging_product: 'whatsapp',\\n          to: adminPhone,\\n          type: 'text',\\n          text: { body: alertMessage }\\n        },\\n        json: true,\\n        timeout: 10000\\n      });\\n      alertSent = true;\\n    } catch (err) {\\n      alertError = (alertError ? alertError + '; ' : '') + err.message;\\n    }\\n  }\\n}\\n\\nreturn [{\\n  json: {\\n    ...input,\\n    alertSent,\\n    alertError,\\n    alertTime: new Date().toISOString()\\n  }\\n}];\\n"},"id":"send-alert","name":"B5 - Send Alert","type":"n8n-nodes-base.code","typeVersion":2,"position":[2950,-200]},{"parameters":{"language":"javascript","jsCode":"// P1-05: Health check passed\\nreturn [{ json: { status: 'HEALTHY', timestamp: new Date().toISOString() } }];\\n"},"id":"end-healthy","name":"END - Healthy","type":"n8n-nodes-base.code","typeVersion":2,"position":[1200,-200]},{"parameters":{"language":"javascript","jsCode":"// P1-05: Not alerting (cooldown or no threshold)\\nreturn [{ json: { status: 'DEGRADED_NO_ALERT', failCount: $json.newFailCount, timestamp: new Date().toISOString() } }];\\n"},"id":"end-no-alert","name":"END - No Alert","type":"n8n-nodes-base.code","typeVersion":2,"position":[1700,100]},{"parameters":{"language":"javascript","jsCode":"// P1-05: Alert sent or attempted\\nreturn [{ json: { status: 'ALERT_SENT', alertSent: $json.alertSent, error: $json.alertError, timestamp: new Date().toISOString() } }];\\n"},"id":"end-alerted","name":"END - Alerted","type":"n8n-nodes-base.code","typeVersion":2,"position":[3200,-200]},{"parameters":{"language":"javascript","jsCode":"// P1-05: Cooldown active, skip alert\\nreturn [{ json: { status: 'COOLDOWN_ACTIVE', timeSinceLastAlert: $json.timeSinceLastAlert, timestamp: new Date().toISOString() } }];\\n"},"id":"end-cooldown","name":"END - Cooldown","type":"n8n-nodes-base.code","typeVersion":2,"position":[2450,0]},{"parameters":{"language":"javascript","jsCode":"// P1-05: Monitor disabled\\nreturn [{ json: { status: 'DISABLED', timestamp: new Date().toISOString() } }];\\n"},"id":"end-disabled","name":"END - Disabled","type":"n8n-nodes-base.code","typeVersion":2,"position":[-50,100]}]	{"CRON - Every 1min":{"main":[[{"node":"B0 - Config","type":"main","index":0}]]},"B0 - Config":{"main":[[{"node":"B0 - Enabled?","type":"main","index":0}]]},"B0 - Enabled?":{"main":[[{"node":"B1 - Get Fail Count","type":"main","index":0}],