gacySharedConfigured && (token === shared);\\n\\n// Meta/Messenger signature verification (X-Hub-Signature-256) - P0-SEC-03\\nconst metaSig = (headers['x-hub-signature-256'] || headers['X-Hub-Signature-256'] || '').toString().trim();\\nconst metaSecret = ($env.META_APP_SECRET || '').toString();\\nconst metaSigMode = ($env.META_SIGNATURE_REQUIRED || 'off').toString().toLowerCase();\\nconst metaSigRequired = (metaSigMode === 'true' || metaSigMode === 'enforce');\\nconst metaSigWarn = (metaSigMode === 'warn');\\n\\nfunction timingSafeEq(a, b) {\\n  try {\\n    const ba = Buffer.from(String(a));\\n    const bb = Buffer.from(String(b));\\n    if (ba.length !== bb.length) return false;\\n    return crypto.timingSafeEqual(ba, bb);\\n  } catch { return false; }\\n}\\n\\nlet metaSigValid = null;\\nlet metaSigReason = '';\\nif (!metaSig) {\\n  metaSigValid = metaSigRequired ? false : null;\\n  metaSigReason = 'signature_missing';\\n} else if (!metaSecret) {\\n  metaSigValid = false;\\n  metaSigReason = 'secret_missing';\\n} else {\\n  const raw = ($json.rawBody && typeof $json.rawBody === 'string') ? $json.rawBody : JSON.stringify(body || {});\\n  const expected = 'sha256=' + crypto.createHmac('sha256', metaSecret).update(raw, 'utf8').digest('hex');\\n  metaSigValid = timingSafeEq(expected, metaSig);\\n  metaSigReason = metaSigValid ? 'ok' : 'invalid';\\n}\\n\\nconst ipRaw = (headers['x-forwarded-for'] || headers['X-Forwarded-For'] || '').toString();\\nconst ip = ipRaw.split(',')[0].trim();\\n\\nconst inboundReceivedAt = new Date().toISOString();\\n\\n// P1-01: Generate correlation ID for end-to-end tracing\\nconst correlationId = (headers['x-correlation-id'] || headers['X-Correlation-Id'] || headers['x-request-id'] || crypto.randomUUID()).toString();\\n\\n// Hints from body (NEVER trusted)\\nconst tenantHint = (body.tenantId || body.tenant_id || body.tenant || '').toString();\\nconst restaurantHint = (body.restaurantId || body.restaurant_id || body.restaurant || '').toString();\\n\\n// Detect canonical envelope\\nconst looksLikeV1 = body && typeof body === 'object' && body.provider && (body.msg_id || body.msgId) && (body.from || body.sender || body.sender_id);\\nconst looksLikeV2 = body && typeof body === 'object' && body.provider && body.sender && body.message && (body.msg_id || body.msgId);\\n\\nfunction buildEnvelopeLegacy() {\\n  const userId = (body.userId || body.from || body.sender || body.sender_id || 'unknown-user').toString();\\n  const msgId = (body.msgId || body.messageId || body.mid || body.message?.id || body.message?.mid || crypto.randomUUID()).toString();\\n  const text = (body.text || body.message?.text || body.message?.body || '').toString();\\n\\n  const buttonId = (body.buttonId || body.interactive?.button_reply?.id || body.message?.buttonId || '').toString();\\n  const audioUrl = (body.audioUrl || body.audio?.url || body.message?.audio?.url || '').toString();\\n  const audioMime = (body.audio?.mime || body.message?.audio?.mime || 'audio/ogg').toString();\\n  const imageUrl = (body.imageUrl || body.image?.url || body.message?.image?.url || '').toString();\\n  const imageMime = (body.image?.mime || body.message?.image?.mime || 'image/jpeg').toString();\\n\\n  let attachments = [];\\n  if (audioUrl) attachments.push({type:'audio', url: audioUrl, mime: audioMime});\\n  if (imageUrl) attachments.push({type:'image', url: imageUrl, mime: imageMime});\\n\\n  const locale = (body.locale || body.meta?.locale || '').toString();\\n  const timezone = (body.timezone || body.meta?.timezone || '').toString();\\n\\n  return {\\n    contract_version: contractVersion === 'unknown' ? 'v1' : contractVersion,\\n    provider: 'msg',\\n    msg_id: msgId,\\n    from: userId,\\n    text: buttonId ? buttonId : text,\\n    timestamp: (body.timestamp || body.time || body.meta?.timestamp || inboundReceivedAt).toString(),\\n    attachments,\\n    meta: {\\n      locale: locale || undefined,\\n      timezone: timezone || undefined,\\n      ip: ip