ormalizedVersion === 'unknown') {\\n  envelope = null;\\n} else if (normalizedVersion === 'v2') {\\n  // strict: if caller requested v2, we validate as v2 (no fallback to v1)\\n  envelope = buildEnvelopeFromV2(body);\\n} else if (normalizedVersion === 'v1' && looksLikeV1 && !looksLikeV2) {\\n  envelope = buildEnvelopeFromV1(body);\\n} else {\\n  // legacy or mismatch => compat layer (v1)\\n  normalizedVersion = 'v1';\\n  envelope = buildEnvelopeLegacy();\\n}\\n\\n// Validate envelope against schema\\nlet isValid = false;\\nlet errors = [];\\nlet schemaHash = '';\\nlet schemaPath = '';\\nlet validator = 'ajv';\\n\\ntry {\\n  if (!envelope) throw new Error('unknown_contract_version');\\n  if ((envelope.provider || '').toString() !== 'msg') throw new Error('provider_mismatch');\\n  const schemasRoot = ($env.SCHEMAS_ROOT || '/opt/resto/schemas').toString();\\n  schemaPath = path.join(schemasRoot, 'inbound', `${envelope.contract_version}.json`);\\n  const schemaText = fs.readFileSync(schemaPath, 'utf8');\\n  schemaHash = crypto.createHash('sha256').update(schemaText).digest('hex');\\n  const schema = JSON.parse(schemaText);\\n\\n  let Ajv;\\n  try { Ajv = require('ajv'); } catch (e) { Ajv = null; }\\n  if (!Ajv) {\\n    validator = 'basic';\\n    // Hard fail: schema validation must be available in production\\n    throw new Error('ajv_not_available');\\n  }\\n  const ajv = new Ajv({allErrors:true, strict:false, allowUnionTypes:true});\\n  const validate = ajv.compile(schema);\\n  isValid = validate(envelope);\\n  if (!isValid) {\\n    errors = (validate.errors || []).slice(0, 10).map(e => ({path: e.instancePath || '', message: e.message || 'invalid'}));\\n  }\\n} catch (err) {\\n  isValid = false;\\n  errors = [{path:'', message: (err && err.message) ? err.message : 'validation_error'}];\\n}\\n\\nconst tokenHash = token ? crypto.createHash('sha256').update(token).digest('hex') : '';\\n\\n// Build internal canonical message (keep existing fields)\\nconst ch = 'messenger';\\nconst userId = envelope?.contract_version === 'v2'\\n  ? (envelope.sender?.id || '').toString()\\n  : (envelope?.from || '').toString();\\n\\nconst msgId = envelope?.contract_version === 'v2'\\n  ? (envelope.msg_id || '').toString()\\n  : (envelope?.msg_id || '').toString();\\n\\nconst text = envelope?.contract_version === 'v2'\\n  ? ((envelope.message?.text || '')).toString()\\n  : ((envelope?.text || '')).toString();\\n\\nconst atts = envelope?.contract_version === 'v2'\\n  ? (Array.isArray(envelope.message?.attachments) ? envelope.message.attachments : [])\\n  : (Array.isArray(envelope.attachments) ? envelope.attachments : []);\\n\\nconst firstAudio = Array.isArray(atts) ? atts.find(a => a && a.type === 'audio' && a.url) : null;\\nconst firstImage = Array.isArray(atts) ? atts.find(a => a && a.type === 'image' && a.url) : null;\\n\\nlet type = 'text';\\nif (firstAudio) type = 'audio';\\nif (firstImage) type = 'image';\\n\\nconst textHash = crypto.createHash('sha256').update((text || '').toString()).digest('hex');\\n\\nreturn [{\\n  json: {\\n    channel: ch,\\n    userId: userId || (body.userId || body.from || body.sender || 'unknown-user').toString(),\\n    tenantId: '',\\n    restaurantId: '',\\n    conversationKey: '',\\n    roleHint: body.roleHint || 'customer',\\n    contract_version: normalizedVersion,\\n    inbound_envelope: envelope,\\n    metadata: {\\n      msgId: msgId || (body.msgId || body.messageId || crypto.randomUUID()).toString(),\\n      timestamp: envelope?.timestamp || inboundReceivedAt,\\n      ip,\\n      userAgent: (headers['user-agent'] || headers['User-Agent'] || '').toString(),\\n      testMode: !!body.testMode\\n    },\\n    message: {\\n      type,\\n      text: (text || '').toString().trim(),\\n      buttonId: '',\\n      audio: firstAudio ? { url: firstAudio.url, mime: firstAudio.mime || 'audio/ogg' } : null,\\n      image: firstImage ? { url: firstImage.url, mime: firstImage.mime || 'image/jpeg' } : null\\n    },\\n    tenant_context_hints: {\\n      tenant_hint: tenantHint || '',\\n      restaurant_hint: restaurantHint || ''\\n    },\\n    _contract: {\\n      version: normalizedVersion,\\n      schemaPath,\\n      schemaHash,\\n      validator,\\n      isValid,\\n      errors\\n    },\\n    _timing: {\\n      inbound_received_at: inboundReceivedAt,\\n      correlation_id: correlationId\\n    },\\n    _auth: {\\n      tokenPresent: !!token,\\n      tokenHash,\\n      legacySharedConfigured,\\n      legacySharedValid,\\n      metaSigPresent: !!metaSig,\\n      metaSigRequired,\\n      metaSigValid,\\n      metaSigReason,\\n      allowQueryToken,\\n      queryTokenProvided,\\n      queryTokenUsed,\\n      tenantHint,\\n      restaurantHint\\n    },\\n    _sec: {\\n      textHash\\n    },\\n    raw: body\\n  }\\n}];\\n"},"id":"9271cba1-3265-41cf-8818-9996067fd826","name":"B0 - Parse & Canonicalize","type":"n8n-nodes-base.code","typeVersion":2,"position":[-2150,0]},{"parameters":{"conditions":{"boolean":[{"value1":"={{$json._auth.authOk}}","operation":"isTrue"},{"value1":"={{$json._auth.scopeOk}}","operation":"isTrue"}]}},"id":"9cb91bc4-475a-48ea-828e-11b249b6ba16","name":"B0 - Token OK?","type":"n8n-nodes-base.if","typeVersion":2,"position":[-1920,0]},{"parameters":{"operation":"executeQuery","query":"WITH ins AS (\\n      INSERT INTO idempotency_keys (conversation_key, msg_id, channel)\\n      VALUES ($1, $2, $3)\\n      ON CONFLICT DO NOTHING\\n      RETURNING 1\\n    )\\n    SELECT COALESCE((SELECT 1 FROM ins), 0) AS inserted;","additionalFields":{"queryParams":"={{[$json.conversationKey, $json.metadata.msgId, $json.channel]}}"}},"id":"1958cc5d-50a6-4fe6-83a8-e3c180d74584","name":"B0 - Idempotency (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[-1700,-120]},{"parameters":{"language":"javascript","jsCode":"// P1-01: Idempotency check result + Redis key preparation\\nconst inserted = Number($json.inserted || 0);\\nconst isNew = inserted === 1;\\n\\n// Prepare Redis key for