ed'];\\n}\\n\\nconst conversationKey = tenantId ? (tenantId + ':' + restaurantId + ':' + e.channel + ':' + e.userId) : '';\\nlet authOk = authMode !== 'deny';\\n\\n// ---- Scopes enforcement (Release-grade)\\n// Required scopes are per-endpoint (here: inbound).\\nconst requiredScopes = ['inbound:write'];\\n\\nfunction hasScope(required, granted) {\\n  if (!required) return true;\\n  const g = new Set((granted || []).map(s => String(s || '').trim()).filter(Boolean));\\n  if (g.has(required)) return true;\\n  if (g.has('*')) return true;\\n  const parts = String(required).split(':');\\n  if (parts.length === 2 && g.has(`${parts[0]}:*`)) return true;\\n  return false;\\n}\\n\\n// Legacy token can keep inbound compatibility, but MUST NOT be used for admin/internal.\\nconst legacyBypass = (authMode === 'legacy_shared') && requiredScopes.some(s => s.startsWith('inbound:'));\\nconst scopeOk = authOk && (legacyBypass || requiredScopes.length === 0 || requiredScopes.some(r => hasScope(r, scopes)));\\n\\nconst endpoint_group = 'inbound';\\nconst endpoint_path = '/v1/inbound/messenger';\\n\\nlet denyReason = authOk ? (scopeOk ? '' : 'SCOPE_DENY') : 'AUTH_DENY';\\n\\n// Meta signature enforcement (fail-close only if META_SIGNATURE_REQUIRED=enforce)\\nconst metaSigRequired = !!e._auth?.metaSigRequired;\\nconst metaSigValid = (e._auth?.metaSigValid === true);\\nconst metaSigPresent = !!e._auth?.metaSigPresent;\\nconst metaSigReason = (e._auth?.metaSigReason || '').toString();\\n\\n// P0-08: Anti-replay timestamp validation\\nconst replayWindowMs = parseInt($env.REPLAY_WINDOW_SECONDS || '300', 10) * 1000;\\nconst replayCheckEnabled = (($env.REPLAY_CHECK_ENABLED || 'true').toString().toLowerCase() === 'true');\\nlet timestampValid = true;\\nlet timestampReason = '';\\n\\nif (replayCheckEnabled && e.metadata?.timestamp) {\\n  const msgTs = e.metadata.timestamp;\\n  let msgTime = 0;\\n  if (typeof msgTs === 'string' && msgTs.includes('T')) {\\n    msgTime = new Date(msgTs).getTime();\\n  } else if (typeof msgTs === 'number' || /^\\\\\\\\d+$/.test(msgTs)) {\\n    const num = Number(msgTs);\\n    msgTime = num > 9999999999 ? num : num * 1000;\\n  } else {\\n    msgTime = new Date(msgTs).getTime();\\n  }\\n  const now = Date.now();\\n  const age = now - msgTime;\\n  if (isNaN(msgTime) || msgTime <= 0) {\\n    timestampValid = true;\\n    timestampReason = 'unparseable';\\n  } else if (age > replayWindowMs) {\\n    timestampValid = false;\\n    timestampReason = 'too_old';\\n  } else if (age < -60000) {\\n    timestampValid = false;\\n    timestampReason = 'future_timestamp';\\n  } else {\\n    timestampReason = 'ok';\\n  }\\n}\\n\\n// hard deny when meta signature is required and invalid/missing\\nif (metaSigRequired && !metaSigValid) {\\n  denyReason = metaSigPresent ? 'MSG_SIGNATURE_INVALID' : 'MSG_SIGNATURE_MISSING';\\n}\\n// deny on replay attack\\nif (replayCheckEnabled && !timestampValid && timestampReason !== 'unparseable') {\\n  denyReason = 'REPLAY_ATTACK_' + timestampReason.toUpperCase();\\n}\\n// deny legacy token if presented but legacy is not allowed\\nif (legacyOk && !legacyAllowed) {\\n  denyReason = 'LEGACY_TOKEN_BLOCKED';\\n}\\n\\nconst tenant_context = {\\n  tenant_id: tenantId || null,\\n  restaurant_id: restaurantId || null,\\n  source: authMode === 'api_client' ? 'auth_db' : (authMode === 'meta_signature' ? 'meta_signature' : (authMode === 'legacy_shared' ? 'legacy_shared' : 'untrusted_payload')),\\n  client_id: matched ? (e.client_id || null) : null,\\n  client_name: matched ? (e.client_name || null) : null,\\n  scopes\\n};\\n\\n\\nreturn [{\\n  json: {\\n    ...e,\\n    tenantId,\\n    restaurantId,\\n    conversationKey,\\n    tenant_context,\\n      _auth: {\\n      ...e._auth,\\n      authOk,\\n      authMode,\\n      scopes,\\n      requiredScopes,\\n      scopeOk,\\n      endpoint_group,\\n      endpoint_path,\\n      denyReason,\\n      clientId: matched ? (e.client_id || null) : null,\\n      clientName: matched ? (e.client_name || null) : null\\n    }\\n  }\\n}];"},"id":"0aba4d61-8e1b-4f65-b17b-a02515c8685f","name":"B0 - Apply Auth Context","type":"n8n-nodes-base.code","typeVersion":2,"position":[480,-120]},{"parameters":{"operation":"executeQuery","query":"INSERT INTO security_events(tenant_id, restaurant_id, conversation_key, channel, user_id, event_type, severity, payload_json) VALUES ($1,$2,$3,$4,$5,$6,'HIGH', jsonb_build_object('token_hash',$7,'ip',$8,'ua',$9,'tenant_hint',$10,'restaurant_hint',$11,'auth_mode',$12,'required_scopes',$13::jsonb,'scopes',$14::jsonb,'endpoint_group',$15,'endpoint_path',$16)) RETURNING 1;","additionalFields":{"queryParams":"={{[null, null, null, $json.channel, $json.userId, ($json._auth.denyReason || 'AUTH_DENY'), $json._auth.tokenHash, $json.metadata.ip, $json.metadata.userAgent, $json._auth.tenantHint, $json._auth.restaurantHint, $json._auth.authMode, JSON.stringify($json._auth.requiredScopes || []), JSON.stringify($json._auth.scopes || []), $json._auth.endpoint_group, $json._auth.endpoint_path]}}"}},"id":"ca8bb2e8-270c-4020-ab57-cc94f9ae2c53","name":"B0 - Log Deny (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[520,80]},{"parameters":{"conditions":{"boolean":[{"value1":"={{$json._contract.isValid}}","operation":"isTrue"}]}},"id":"17b88af7-e086-4b06-8074-342d88806d97","name":"B0 - Contract Valid?","type":"n8n-nodes-base.if","typeVersion":1,"position":[-1900,0]},{"parameters":{"operation":"executeQuery","query":"INSERT INTO security_events(tenant_id, restaurant_id, conversation_key, channel, user_id, event_type, severity, payload_json) VALUES (NULL,NULL,NULL,$1,$2,'CONTRACT_VALIDATION_FAILED','MEDIUM', jsonb_build_object('contract_version',$3,'schema_hash',$4,'errors',$5,'ip',$6,'ua',$7)) RETURNING 1;","additionalFields":{"queryParams":"={{[$json.channel, $json.userId, $json._contract.version, $json._contract.schemaHash, $json._contract.errors, $json.metadata.ip, $json.metadata.userAgent]}}"}},"id":"5ac2d302-2225-4622-8961-9