W_AI_STRATEGY_ADVISOR	t	[{"parameters":{"rule":{"interval":[{"field":"hours","hoursInterval":1}]}},"name":"Hourly Analysis","type":"n8n-nodes-base.scheduleTrigger","typeVersion":1,"position":[100,300],"id":"c542e2ae-0e70-41a0-8541-6d459d760f54"},{"parameters":{"operation":"getAll","collection":"orders","filters":{"createdAt":{"$gte":"={{ new Date(Date.now() - 86400000).toISOString() }}"}},"limit":500},"name":"Get Last 24h Orders","type":"n8n-nodes-base.strapi","typeVersion":1,"position":[300,300],"id":"917a0d1a-9a86-4f57-a5ab-d0255727c7a9"},{"parameters":{"jsCode":"const orders = $input.all().map(i => i.json);\\n\\n// Aggregate sales by product\\nconst productSales = {};\\norders.forEach(o => {\\n  (o.items || []).forEach(item => {\\n    const name = item.product_name || 'Unknown';\\n    productSales[name] = (productSales[name] || 0) + (item.quantity || 1);\\n  });\\n});\\n\\n// Sort by sales\\nconst sorted = Object.entries(productSales)\\n  .sort((a, b) => b[1] - a[1]);\\n\\nconst top3 = sorted.slice(0, 3).map(([name, qty]) => ({ name, qty }));\\nconst bottom3 = sorted.slice(-3).map(([name, qty]) => ({ name, qty }));\\n\\nreturn {\\n  json: {\\n    total_orders: orders.length,\\n    top_sellers: top3,\\n    low_performers: bottom3,\\n    analysis_time: new Date().toISOString()\\n  }\\n};"},"name":"Analyze Sales","type":"n8n-nodes-base.code","typeVersion":1,"position":[500,300],"id":"08ba861a-61cd-4733-8794-ad2d68454361"},{"parameters":{"url":"={{ $env.LLM_API_URL || 'http://ollama:11434/api/chat' }}","method":"POST","sendBody":true,"bodyParameters":{"parameters":[{"name":"model","value":"={{ $env.LLM_MODEL || 'llama3.1' }}"},{"name":"stream","value":"={{ false }}"},{"name":"messages","value":"={{ [{ \\"role\\": \\"system\\", \\"content\\": \\"Tu es un consultant stratégique pour restaurant. Analyse les données et donne UN conseil actionnable en 2 lignes max. Sois direct et parle comme un pote entrepreneur.\\" }, { \\"role\\": \\"user\\", \\"content\\": `Voici les s