\\n}\\n\\nconst conversationKey = tenantId ? (tenantId + ':' + restaurantId + ':' + e.channel + ':' + e.userId) : '';\\nlet authOk = authMode !== 'deny';\\n\\n// ---- Scopes enforcement (Release-grade)\\n// Required scopes are per-endpoint (here: inbound).\\nconst requiredScopes = ['inbound:write'];\\n\\nfunction hasScope(required, granted) {\\n  if (!required) return true;\\n  const g = new Set((granted || []).map(s => String(s || '').trim()).filter(Boolean));\\n  if (g.has(required)) return true;\\n  if (g.has('*')) return true;\\n  const parts = String(required).split(':');\\n  if (parts.length === 2 && g.has(`${parts[0]}:*`)) return true;\\n  return false;\\n}\\n\\n// Legacy token can keep inbound compatibility, but MUST NOT be used for admin/internal.\\nconst legacyBypass = (authMode === 'legacy_shared') && requiredScopes.some(s => s.startsWith('inbound:'));\\nconst scopeOk = authOk && (legacyBypass || requiredScopes.length === 0 || requiredScopes.some(r => hasScope(r, scopes)));\\n\\nconst endpoint_group = 'inbound';\\nconst endpoint_path = '/v1/inbound/instagram';\\n\\nlet denyReason = authOk ? (scopeOk ? '' : 'SCOPE_DENY') : 'AUTH_DENY';\\n\\n// Meta signature enforcement (fail-close only if META_SIGNATURE_REQUIRED=enforce)\\nconst metaSigRequired = !!e._auth?.metaSigRequired;\\nconst metaSigValid = (e._auth?.metaSigValid === true);\\nconst metaSigPresent = !!e._auth?.metaSigPresent;\\nconst metaSigReason = (e._auth?.metaSigReason || '').toString();\\n\\n// P0-08: Anti-replay timestamp validation\\nconst replayWindowMs = parseInt($env.REPLAY_WINDOW_SECONDS || '300', 10) * 1000;\\nconst replayCheckEnabled = (($env.REPLAY_CHECK_ENABLED || 'true').toString().toLowerCase() === 'true');\\nlet timestampValid = true;\\nlet timestampReason = '';\\n\\nif (replayCheckEnabled && e.metadata?.timestamp) {\\n  const msgTs = e.metadata.timestamp;\\n  let msgTime = 0;\\n  if (typeof msgTs === 'string' && msgTs.includes('T')) {\\n    msgTime = new Date(msgTs).getTime();\\n  