","index":0}]]},"S2 - Apply FAQ Result":{"main":[[{"node":"S4 - Is Support Handoff?","type":"main","index":0}]]},"Sx - PassThrough":{"main":[[{"node":"S4 - Is Support Handoff?","type":"main","index":0}]]},"S4 - Is Support Handoff?":{"main":[[{"node":"S5 - Upsert Ticket (DB)","type":"main","index":0}],[{"node":"C7 - Save State+Cart (DB)","type":"main","index":0}]]},"S5 - Upsert Ticket (DB)":{"main":[[{"node":"S6 - Log Ticket Message (DB)","type":"main","index":0}]]},"S6 - Log Ticket Message (DB)":{"main":[[{"node":"S7 - Ensure Support Reply","type":"main","index":0}]]},"S7 - Ensure Support Reply":{"main":[[{"node":"C7 - Save State+Cart (DB)","type":"main","index":0}]]}}	2026-02-22 20:56:05.016+00	2026-02-22 20:56:05.016+00	{"executionTimeout":300,"saveExecutionProgress":true,"saveManualExecutions":true}	\N	\N	5848fe8a-a43b-4a97-8166-130fe52fbc4e	0	hfMCZrWtHRG0srhn	\N	\N	f	2	\N	\N
W4_CORE_ALGERIAN_STUB	t	[{"parameters":{},"name":"Message Input","type":"n8n-nodes-base.start","typeVersion":1,"position":[100,300],"id":"e27c6b26-2f5a-4067-87da-df1ebab27752"},{"parameters":{"operation":"get","collection":"restaurant-brand","id":"singleton"},"name":"Get Brand Config","type":"n8n-nodes-base.strapi","typeVersion":1,"position":[250,300],"id":"5a59d9df-b487-4e34-a631-d7297cf3464d"},{"parameters":{"jsCode":"// Détection de langue Algérienne\\nconst text = $input.first().json.text || '';\\nconst brand = $node['Get Brand Config'].json;\\n\\n// Patterns Darija\\nconst darijaPatterns = /\\\\b(sahit|bsaha|chhal|wesh|khouya|rabi|inchallah|baraka|rabbi yahafdek|bghit|3andi)\\\\b/i;\\n\\n// Patterns Arabe\\nconst arabicPattern = /[\\\\u0600-\\\\u06FF]/;\\n\\n// Patterns Français\\nconst frenchPattern = /\\\\b(bonjour|merci|salut|commander|livraison)\\\\b/i;\\n\\nlet detectedLang = 'fr';\\nlet mixedMode = false;\\n\\nif (arabicPattern.test(text)) {\\n  detectedLang = 'ar';\\n}\\n\\nif (darijaPatterns.test(text)) {\\n  detectedLang = 'dz';\\n  if (frenchPattern.test(text)) {\\n    mixedMode = true;\\n  }\\n}\\n\\nreturn {\\n  json: {\\n    text: text,\\n    detected_language: detectedLang,\\n    mixed_mode: mixedMode,\\n    brand: brand\\n  }\\n};"},"name":"Language Detection (DZ Market)","type":"n8n-nodes-base.code","typeVersion":1,"position":[400,300],"id":"2607d939-1033-4628-81c4-9ccaf182cea1"},{"parameters":{"url":"={{ $env.LLM_API_URL || 'http://ollama:11434/api/chat' }}","method":"POST","sendBody":true,"bodyParameters":{"parameters":[{"name":"model","value":"={{ $env.LLM_MODEL || 'llama3.1' }}"},{"name":"stream","value":"={{ false }}"},{"name":"messages","value":"={{ [\\n  {\\n    \\"role\\": \\"system\\",\\n    \\"content\\": `Tu es l'assistant conversationnel de '${$json.brand.restaurant_name}'.\\n\\nIDENTITÉ & MARCHÉ:\\n- Marché: ALGÉRIE (Français, Darija, Arabe)\\n- Ton: ${$json.brand.voice_tone}\\n- Histoire: ${$json.brand.brand_story}\\n\\nRÈGLES LINGUISTIQUES:\\n1. LANGUE DÉTECTÉE: ${$json.detected_language}\\n2. CODE-SWITCHING: ${$json.mixed_mode ? 'OUI' : 'NON'}\\n3. EXPRESSIONS DARIJA: ${JSON.stringify($json.brand.localization?.darija_expressions || [])}\\n4. Réponds dans la langue du client\\n5. Si Darija: utilise expressions naturelles\\n6. Sois concis et chaleureux\\n\\nTÂCHE: Aide le client en respectant SA langue.`\\n  },\\n  {\\n    \\"role\\": \\"user\\",\\n    \\"content\\": $json.text\\n  }\\n] }}"}]}},"name":"Ollama Chat (Local)","type":"n8n-nodes-base.httpRequest","typeVersion":3,"position":[600,300],"id":"70973e41-650d-46d3-b41f-f5058f4a1d9a"}]	{"Message Input":{"main":[[{"node":"Get Brand Config","type":"main","index":0}]]},"Get Brand Config":{"main":[[{"node":"Language Detection (DZ Market)","type":"main","index":0}]]},"Language Detection (DZ Market)":{"main":[[{"node":"Ollama Chat (Local)","type":"main","index":0}]]}}	2026-02-22 20:56:05.016+00	2026-02-22 20:56:05.016+00	\N	\N	\N	15747431-071b-4b32-90de-ff3d282ae50f	0	fn7K9ZUitupxuPCD	\N	\N	f	2	\N	\N
W4_CORE_MENU_GROUNDED	t	[{"parameters":{},"name":"User Message","type":"n8n-nodes-base.start","typeVersion":1,"position":[100,300],"id":"aaf4daae-4f19-4252-8d9a-e3bcc62f4dce"},{"parameters":{"workflowId":"={{ $env.MENU_VALIDATOR_WORKFLOW_ID }}"},"name":"Load Menu","type":"n8n-nodes-base.executeWorkflow","typeVersion":1,"position":[250,300],"id":"ff9218b6-d9b6-4ee0-a72c-b65a6627023d"},{"parameters":{"operation":"get","collection":"restaurant-brand","id":"singleton"},"name":"Get Brand DNA","type":"n8n-nodes-base.strapi","typeVersion":1,"position":[250,450],"id":"7a42370c-241d-4a0f-9278-64d4451f5de7"},{"parameters":{"jsCode":"const menu = $input.item(0).json;\\nconst brand = $input.item(1).json;\\nconst userText = menu.user_text;\\n\\n// Language detection (Darija patterns)\\nconst darijaPatterns = /\\\\b(sahit|bsaha|chhal|wesh|khouya|rabbi|bghit|3andi)\\\\b/i;\\nconst arabicPattern = /[\\\\u0600-\\\\u06FF]/;\\nconst detectedLang = arabicPattern.test(userText) ? 'ar' : (darijaPatterns.test(userText) ? 'dz' : 'fr');\\n\\nreturn {\\n  json: {\\n    user_text: userText,\\n    menu: menu.menu_formatted,\\n    menu_index: menu.menu_index,\\n    brand: brand,\\n    detected_lang: detectedLang\\n  }\\n};"},"name":"Merge Context","type":"n8n-nodes-base.code","typeVersion":1,"position":[450,300],"id":"c1c65824-0b97-40bb-8d56-6001a902cb21"},{"parameters":{"url":"={{ $env.LLM_API_URL || 'http://ollama:11434/api/chat' }}","method":"POST","sendBody":true,"bodyParameters":{"parameters":[{"name":"model","value":"={{ $env.LLM_MODEL || 'llama3.1' }}"},{"name":"stream","value":"={{ false }}"},{"name":"messages","value":"={{ [\\n  {\\n    \\"role\\": \\"system\\",\\n    \\"content\\": `Tu es l'assistant de commande pour '${$json.brand.restaurant_name}'.\\n\\nRÈGLE ABSOLUE: TU NE PEUX SUGGÉRER QUE LES PLATS CI-DESSOUS. N'INVENTE JAMAIS.\\n\\n=== MENU RÉEL ===\\n${$json.menu}\\n=================\\n\\nLANGUE: ${$json.detected_lang}\\nTON: ${$json.brand.voice_tone}\\nMARCHÉ: Algérie (FR/Darija/AR)\\n\\nINSTRUCTIONS:\\n1. Si le client demande un nom signature (\\"Bazooka\\"), trouve-le dans les alias\\n2. Si rupture (❌), propose une alternative RÉELLE\\n3. Utilise les VRAIS prix\\n4. Si inexistant: \\"On n'a pas ça chef, mais regarde notre menu\\"\\n5. Réponds dans la langue du client\\n6. Si Darija: expressions naturelles (sahit, bsaha, chhal)\\n7. Sois concis, naturel, comme un vrai serveur algérien\\n\\nEXEMPLE:\\nClient: \\"Wesh, vous avez le Bazooka ?\\"\\nToi: \\"Sahit chef ! Oui le Bazooka est dispo 🔥 - 800 DA. Tu veux l'ajouter ?\\"`\\n  },\\n  {\\n    \\"role\\": \\"user\\",\\n    \\"content\\": $json.user_text\\n  }\\n] }}"}]}},"name":"Ollama Chat (Local AI)","type":"n8n-nodes-base.httpRequest","typeVersion":3,"position":[650,300],"id":"72523ffb-db80-4f76-93a4-e72072aab4c7"},{"parameters":{"jsCode":"// Extract response from Ollama format\\nconst ollamaResponse = $input.first().json;\\nconst content = ollamaResponse.message?.content || ollamaResponse.response || '';\\n\\nreturn {\\n  json: {\\n    response: content,\\n    model: ollamaResponse.model,\\n    done: ollamaResponse.done\\n  }\\n};"},"name":"Format Response","type":"n8n-nodes-base.code","typeVersion":1,"position":[850,300],"id":"e425eb05-ed3f-49d0-a894-35d2d523b479"}]	{"User Message":{"main":[[{"node":"Load Menu","type":"main","index":0},{"node":"Get Brand DNA","type":"main","index":0}]]},"Load Menu":{"main":[[{"node":"Merge Context","type":"main","index":0}]]},"Get Brand DNA":{"main":[[{"node":"Merge Context","type":"main","index":0}]]},"Merge Context":{"main":[[{"node":"Ollama Chat (Local AI)","type":"main","index":0}]]},"Ollama Chat (Local AI)":{"main":[[{"node":"Format Response","type":"main","index":0}]]}}	2026-02-22 20:56:05.016+00	2026-02-22 20:56:05.016+00	\N	\N	\N	22f083fb-38ee-4057-bb9d-29b831b1c044	0	m5HRtDques4eXF0K	\N	\N	f	2	\N	\N
