ue1":"={{$json._auth.authOk}}","operation":"isTrue"},{"value1":"={{$json._auth.scopeOk}}","operation":"isTrue"}]}},"id":"175f9c4e-220c-4c20-ba0f-c14397ae124b","name":"B0 - Access OK?","type":"n8n-nodes-base.if","typeVersion":2,"position":[-280,0]},{"parameters":{"operation":"executeQuery","query":"INSERT INTO security_events(tenant_id, restaurant_id, conversation_key, channel, user_id, event_type, severity, payload_json) VALUES ($1,$2,$3,$4,$5,$6,'HIGH', jsonb_build_object('token_hash',$7,'ip',$8,'ua',$9,'auth_mode',$10,'required_scopes',$11::jsonb,'scopes',$12::jsonb,'endpoint_group',$13,'endpoint_path',$14)) RETURNING 1;","additionalFields":{"queryParams":"={{[$json.tenantId||null,$json.restaurantId||null,null,$json.channel,$json.userId,($json._auth.denyReason||'AUTH_DENY'),$json._auth.tokenHash,$json.metadata.ip,$json.metadata.userAgent,$json._auth.authMode,JSON.stringify($json._auth.requiredScopes||[]),JSON.stringify($json._auth.scopes||[]),$json._auth.endpoint_group,$json._auth.endpoint_path]}}"}},"id":"140c1332-ebcd-44fb-a35b-ecd63221a888","name":"B0 - Log Deny (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[-40,120]},{"parameters":{"responseCode":403,"responseData":"={{ { ok: false, error: ($json._auth.denyReason || 'AUTH_DENY'), message: 'Forbidden' } }}"},"id":"961b9a67-cda8-402e-9446-2a97396b1987","name":"RESP - 403 Forbidden","type":"n8n-nodes-base.respondToWebhook","typeVersion":1,"position":[220,120]},{"parameters":{"operation":"executeQuery","query":"INSERT INTO admin_audit_log(tenant_id, restaurant_id, actor_client_id, actor_name, action, object_type, object_id, ip, user_agent, payload_json) VALUES ($1,$2,$3,$4,'ADMIN_ORDERS_LIST',NULL,NULL,$5,$6,jsonb_build_object('scopes',$7::jsonb)) RETURNING id;","additionalFields":{"queryParams":"={{[$json.tenantId||null,$json.restaurantId||null,$json._auth.clientId||null,$json._auth.clientName||null,$json.metadata.ip,$json.metadata.userAgent,JSON.stringify($json._auth.scopes||[])]}}"}},"id":"eeefd920-827e-495e-b152-a2158bcf1443","name":"B0 - Log Allow (Audit)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[-40,-120]},{"parameters":{"language":"javascript","jsCode":"const e = $json;\\nconst q = (e.query || {});\\n\\nconst rawStatus = (q.status || '').toString().trim();\\nconst rawFrom = (q.date_from || q.from || '').toString().trim();\\nconst rawTo = (q.date_to || q.to || '').toString().trim();\\nconst rawLimit = (q.limit || '').toString().trim();\\nconst includeTimeline = ['1','true','yes','y','on'].includes(String(q.include_timeline || '').toLowerCase());\\nconst exportFmt = (q.export || '').toString().trim().toLowerCase();\\n\\nconst limit = Math.max(1, Math.min(500, parseInt(rawLimit || '100', 10) || 100));\\n\\nfunction parseDate(s){\\n  if(!s) return null;\\n  const d = new Date(s);\\n  if(!isNaN(d.getTime())) return d.toISOString();\\n  return null;\\n}\\nlet dateFrom = parseDate(rawFrom);\\nlet dateTo = parseDate(rawTo);\\nif(!dateFrom){\\n  const d = new Date(Date.now() - 7*24*3600*1000);\\n  dateFrom = d.toISOString();\\n}\\n\\nlet statusesPg = null;\\nif(rawStatus){\\n  const s = rawStatus.toUpperCase();\\n  const map = {\\n    'CONFIRMED':['ACCEPTED'],\\n    'PREPARING':['IN_PROGRESS'],\\n    'READY':['READY'],\\n    'OUT_FOR_DELIVERY':['OUT_FOR_DELIVERY'],\\n    'DELIVERED':['DONE','DELIVERED'],\\n    'CANCELLED':['CANCELLED']\\n  };\\n  const arr = (map[s] || [s]).map(x => String(x).replace(/[^A-Z0-9_]/g,'')).filter(Boolean);\\n  if(arr.length) statusesPg = '{' + arr.join(',') + '}';\\n}\\n\\nreturn [{json:{...e,_filters:{rawStatus,dateFrom,dateTo,limit,includeTimeline,exportFmt,statusesPg}}}];"},"id":"d146b334-c03d-4a0e-bee0-f54f1bcafe7e","name":"Q1 - Parse Filters","type":"n8n-nodes-base.code","typeVersion":2,"position":[220,-120]},{"parameters":{"operation":"executeQuery","query":"SELECT\\n  o.order_id,\\n  o.status,\\n  public.map_order_status_to_customer(o.status, o.service_mode) AS customer_status,\\n  o.service_mode,\\n  o.total_cents,\\n  o.created_at,\\n  o.updated_at,\\n  o.channel,\\n  o.user_id,\\n  o.delivery_wilaya,\\n  o.delivery_commune,\\n  o.delivery_eta_min,\\n  o.delivery_eta_max,\\n  CASE WHEN $6::boolean THEN (\\n    SELECT COALESCE(jsonb_agg(\\n      jsonb_build_object('at', h.created_at,'internal_status', h.internal_status,'customer_status', h.customer_status)\\n      ORDER BY h.created_at\\n    ), '[]'::jsonb)\\n    FROM order_status_history h\\n    WHERE h.order_id = o.order_id\\n  ) ELSE '[]'::jsonb END AS timeline\\nFROM orders o\\nWHERE o.tenant_id = $1\\n  AND ($2::text[] IS NULL OR o.status = ANY($2::text[]))\\n  AND ($3::timestamptz IS NULL OR o.created_at >= $3)\\n  AND ($4::timestamptz IS NULL OR o.created_at <= $4)\\nORDER BY o.created_at DESC\\nLIMIT $5;","additionalFields":{"queryParams":"={{[$json.tenantId,$json._filters.statusesPg,$json._filters.dateFrom,$json._filters.dateTo,$json._filters.limit,$json._filters.includeTimeline]}}"}},"id":"b8bd7aec-55e1-4903-8617-16878f73075d","name":"Q2 - List Orders (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[460,-120]},{"parameters":{"language":"javascript","jsCode":"const ctx = $items('Q1 - Parse Filters')[0].json;\\nconst rows = $items('Q2 - List Orders (DB)').map(i => i.json);\\n\\nfunction toCsv(rows){\\n  const header=['order_id','status','customer_status','service_mode','total_cents','created_at','delivery_wilaya','delivery_commune','delivery_eta_min','delivery_eta_max'];\\n  const esc=(v)=>{const s=(v===null||v===undefined)?'':String(v); if(/[\\n\\r\\",]/.test(s)) return '\\"'+s.replace(/\\"/g,'\\"\\"')+'\\"'; return s;};\\n  const lines=[header.join(',')];\\n  for(const r of rows){ lines.push(header.map(k=>esc(r[k])).join(',')); }\\n  return lines.join('\\n');\\n}\\n\\nif((ctx._filters.exportFmt||'').toLowerCase()==='csv'){\\n  return [{json:{...ctx,_response:{body:toCsv(rows),headers:{'Content-Type':'text/csv; charset=utf-8'}}}}];\\n}\\nreturn [{json:{...ctx,_response:{body:{ok:true,