W14 - ADMIN WA Support Console	t	[{"parameters":{},"id":"c97073dd-abe4-4ad0-b23c-80e221f13d5c","name":"IN - From Adapters","type":"n8n-nodes-base.executeWorkflowTrigger","typeVersion":1,"position":[-1200,0]},{"parameters":{"language":"javascript","jsCode":"const e = $json;\\nconst msgText = (e.message?.text || '').toString().trim();\\nconst buttonId = (e.message?.buttonId || '').toString().trim();\\nconst text = (e.message?.type === 'button') ? buttonId : msgText;\\n\\nconst enabled = (($env.ADMIN_WA_CONSOLE_ENABLED || 'false').toString().toLowerCase() === 'true');\\nconst strictAr = (($env.STRICT_AR_OUT || 'true').toString().toLowerCase()==='true');\\nconst hasArabic = /[؀-ۿݐ-ݿࢠ-ࣿ]/.test(msgText || '');\\nconst locale = (strictAr && hasArabic) ? 'ar' : 'fr';\\n\\nconst raw = (text || '').trim();\\nconst isCmd = raw.startsWith('!');\\nconst parts = raw.replace(/^!+/, '!').slice(1).trim().split(/\\\\s+/).filter(Boolean);\\nconst cmd = (parts[0] || '').toLowerCase();\\nconst args = parts.slice(1);\\n\\nreturn [{json:{\\n  ...e,\\n  adminConsole: {\\n    enabled,\\n    raw,\\n    isCmd,\\n    cmd,\\n    args,\\n    // for reply: keep original tail text\\n    tail: raw.startsWith('!reply') ? raw.replace(/^!reply\\\\s+/i,'') : '',\\n    hasArabic,\\n    locale\\n  }\\n}}];"},"id":"83d4a8d6-8ba5-4cc6-943c-aca030dae219","name":"A0 - Parse Command","type":"n8n-nodes-base.code","typeVersion":2,"position":[-980,0]},{"parameters":{"conditions":{"boolean":[{"value1":"={{$json.adminConsole.enabled === true && $json.adminConsole.isCmd === true}}","operation":"isTrue"}]}},"id":"0b339863-1ee0-44f2-afd3-a29cbf244184","name":"A1 - Is Admin Command?","type":"n8n-nodes-base.if","typeVersion":2,"position":[-760,0]},{"parameters":{"language":"javascript","jsCode":"return $input.all();"},"id":"fb5ff687-c8dd-4da0-add1-4792d8962c67","name":"END - Drop","type":"n8n-nodes-base.code","typeVersion":2,"position":[-520,180]},{"parameters":{"operation":"executeQuery","query":"-- P2-02: Check both RBAC table and phone allowlist\\nWITH rbac_check AS (\\n  SELECT role, 'rbac' AS source\\n  FROM restaurant_users\\n  WHERE tenant_id=$1 AND restaurant_id=$2 AND channel='whatsapp' AND user_id=$3 AND role IN ('admin','owner')\\n  LIMIT 1\\n),\\nphone_check AS (\\n  SELECT role, 'phone_allowlist' AS source, permissions\\n  FROM admin_phone_allowlist\\n  WHERE phone_number=$3 AND is_active=true\\n  LIMIT 1\\n)\\nSELECT COALESCE(r.role, p.role) AS role,\\n       COALESCE(r.source, p.source) AS auth_source,\\n       p.permissions\\nFROM rbac_check r\\nFULL OUTER JOIN phone_check p ON true\\nWHERE r.role IS NOT NULL OR p.role IS NOT NULL\\nLIMIT 1;","additionalFields":{"queryParams":"={{[$json.tenantId, $json.restaurantId, $json.userId]}}"}},"id":"698418e6-d709-4690-b9e6-66a3c5c9f806","name":"A2 - RBAC (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[-520,0]},{"parameters":{"conditions":{"number":[{"value1":"={{($json.data && $json.data.length) ? 1 : 0}}","operation":"larger","value2":0}]}},"id":"ce280986-6f0b-4dc4-88cb-a70ae58b50d2","name":"A3 - Authorized?","type":"n8n-nodes-base.if","typeVersion":2,"position":[-320,0]},{"parameters":{"language":"javascript","jsCode":"const e = $json;\\nconst reply = '⛔️ Accès refusé. (admin uniquement)';\\nreturn [{json:{...e, adminReplyText: reply}}];"},"id":"1f5b76e0-9a56-4c1a-bd70-44a33a2ae63b","name":"A4 - Not Authorized","type":"n8n-nodes-base.code","typeVersion":2,"position":[-120,180]},{"parameters":{"language":"javascript","jsCode":"const e = $json;\\nconst cmd = (e.adminConsole?.cmd || '').toLowerCase();\\nconst args = Array.isArray(e.adminConsole?.args) ? e.adminConsole.args : [];\\nconst raw = (e.adminConsole?.raw || '').toString();\\n\\nfunction usage() {\\n  return [\\n    '*Console Admin P2-02*',\\n    '',\\n    '*Statut & Monitoring*',\\n    '- !status',\\n    '- !flags [list]',\\n    '- !flags set <FLAG> <VALUE>',\\n    '',\\n    '*Dead Letter Queue*',\\n    '- !dlq list [limit]',\\n    '- !dlq show <outbound_id>',\\n    '- !dlq replay <outbound_id>',\\n    '- !dlq drop <outbound_id>',\\n    '',\\n    '*Support Tickets*',\\n    '- !help',\\n    '- !tickets [open|all]',\\n    '- !take <ticket_id>',\\n    '- !close <ticket_id>',\\n    '- !reply <ticket_id> <message>',\\n    '',\\n    '*Templates (FR/AR/Darija)*',\\n    '- !template get <KEY> [fr|ar|darija]',\\n    '- !template set <KEY> [locale] <CONTENT...>',\\n    '',\\n    '*Commandes (P2-DZ-01)*',\\n    '- !order list [limit] [status]',\\n    '- !order show <id>',\\n    '- !order noshow <id>',\\n    '- !order cancel <id> [reason]',\\n    '- !order delivered <id>',\\n    '',\\n    '*Clients*',\\n    '- !customer risk <phone>',\\n    '- !customer blacklist <phone> [reason]',\\n    '- !customer unblock <phone>',\\n    '',\\n    '*Delivery Zones*',\\n    '- !zone list',\\n    '- !zone set <wilaya> ; <commune> ; <fee> ; <min> ; <eta_min> ; <eta_max> ; <active>'\\n  ].join('\\n');\\n}\\n\\n\\nfunction normLocale(x) {\\n  const l = (x || 'fr').toString().trim().toLowerCase();\\n  return (l.startsWith('ar')) ? 'ar' : 'fr';\\n}\\n\\nlet action = 'HELP';\\nlet ticketId = null;\\nlet filter = 'open';\\nlet message = '';\\n\\nlet templateKey = null;\\nlet templateLocale = 'fr';\\nlet templateContent = '';\\nlet templateVars = [];\\n\\nlet zoneWilaya = null;\\nlet zoneCommune = null;\\nlet zoneFee = null;\\nlet zoneMin = null;\\nlet zoneEtaMin = null;\\nlet zoneEtaMax = null;\\nlet zoneActive = null;\\nlet zoneOp = null;\\n\\nif (!cmd || cmd === 'help') action = 'HELP';\\nelse if (cmd === 'tickets') { action = 'TICKETS'; filter = (args[0]||'open').toLowerCase(); }\\nelse if (cmd === 'take') { action = 'TAKE'; ticketId = parseInt(args[0]||'0',10)||0; }\\nelse if (cmd === 'close') { action = 'CLOSE'; ticketId = parseInt(args[0]||'0',10)||0; }\\nelse if (cmd === 'reply') {\\n  action = 'REPLY';\\n  // raw tail: \\"<id> <message>\\"\\n  const tail = (e.adminConsole?.tail || '').trim();\\n  const m = tail.match(/^(\\\\d+)\\\\s+([\\\\s\\\\S]{1,2000})$/);\\n  ticketId = m ? (parseInt(m[1],10)||0) : 0;\\n  message = m ? m[2].trim() : '';\\n}\\nelse if (cmd === 'template') {\\n  const sub = (args[0] || '').toLowerCase();\\n  templateKey = (args[1] || '').toString().trim();\\n  // locale can be args[2] if looks like fr/ar\\n  const maybeLoc = (args[2] || '').toString().trim();\\n  const hasLoc = /^(fr|ar)([-_].+)?$/i.test(maybeLoc);\\n  templateLocale = normLocale(hasLoc ? maybeLoc : 'fr');\\n\\n  if (!templateKey) {\\n    action = 'UNKNOWN';\\n  } else if (sub === 'get') {\\n    action = 'TEMPLATE_GET';\\n  } else if (sub === 'set') {\\n    action = 'TEMPLATE_SET';\\n    // Parse tail: !template set KEY [loc] CONTENT...\\n    const m = raw.match(/^!template\\\\s+set\\\\s+([^\\\\s]+)\\\\s+((fr|ar)([-_].+)?)?\\\\s*([\\\\s\\\\S]{0,4000})$/i);\\n    if (m) {\\n      templateKey = m[1].trim();\\n      templateLocale = normLocale(m[2]);\\n      templateContent = (m[5] || '').toString().trim();\\n    } else {\\n      templateContent = args.slice(2 + (hasLoc ? 1 : 0)).join(' ').trim();\\n    }\\n    if (templateContent.length > 2000) templateContent = templateContent.slice(0, 2000);\\n  } else if (sub === 'vars') {\\n    action = 'TEMPLATE_VARS';\\n    const rest = args.slice(2 + (hasLoc ? 1 : 0)).join(' ').trim();\\n    templateVars = rest.split(/[\\\\s,]+/).map(s => s.trim()).filter(Boolean);\\n  } else {\\n    action = 'UNKNOWN';\\n  }\\n}\\n\\nelse if (cmd === 'zone' || cmd === 'delzone') {\\n  const sub = (args[0] || 'list').toLowerCase();\\n  zoneOp = sub;\\n  if (sub === 'list' || sub === 'ls') {\\n    action = 'ZONE_LIST';\\n  } else if (sub === 'set' || sub === 'add' || sub === 'upsert') {\\n    action = 'ZONE_SET';\\n    const m = raw.match(/^!zone\\\\s+(set|add|upsert)\\\\s+([\\\\s\\\\S]{1,500})$/i);\\n    const tail = (m ? m[2] : '').toString();\\n    const parts = tail.split(';').map(s => s.trim()).filter(Boolean);\\n    zoneWilaya = parts[0] || (args[1] || null);\\n    zoneCommune = parts[1] || (args[2] || null);\\n    zoneFee = parseInt(parts[2] || args[3] || '0', 10) || 0;\\n    zoneMin = parseInt(parts[3] || args[4] || '0', 10) || 0;\\n    zoneEtaMin = parseInt(parts[4] || args[5] || '45', 10) || 45;\\n    zoneEtaMax = parseInt(parts[5] || args[6] || '60', 10) || 60;\\n    const actRaw = (parts[6] || args[7] || 'true').toString().trim().toLowerCase();\\n    zoneActive = !(actRaw === 'false' || actRaw === '0' || actRaw === 'off' || actRaw === 'inactive');\\n    if (!zoneWilaya || !zoneCommune) action = 'UNKNOWN';\\n  } else if (sub === 'del' || sub === 'delete' || sub === 'rm') {\\n    action = 'ZONE_DELETE';\\n    const m = raw.match(/^!zone\\\\s+(del|delete|rm)\\\\s+([\\\\s\\\\S]{1,200})$/i);\\n    const tail = (m ? m[2] : '').toString();\\n    const parts = tail.split(';').map(s => s.trim()).filter(Boolean);\\n    zoneWilaya = parts[0] || (args[1] || null);\\n    zoneCommune = parts[1] || (args[2] || null);\\n    if (!zoneWilaya || !zoneCommune) action = 'UNKNOWN';\\n  } else {\\n    action = 'UNKNOWN';\\n  }\\n}\\n\\n\\n// P2-02: STATUS command\\nelse if (cmd === 'status') {\\n  action = 'STATUS';\\n}\\n// P2-02: FLAGS command\\nelse if (cmd === 'flags' || cmd === 'flag') {\\n  const sub = (args[0] || 'list').toLowerCase();\\n  if (sub === 'list' || sub === 'ls' || !args[0]) {\\n    action = 'FLAGS_LIST';\\n  } else if (sub === 'set') {\\n    action = 'FLAGS_SET';\\n    e.adminFlagKey = (args[1] || '').toString().toUpperCase();\\n    e.adminFlagValue = (args[2] || '').toString();\\n  } else if (sub === 'unset' || sub === 'del') {\\n    action = 'FLAGS_UNSET';\\n    e.adminFlagKey = (args[1] || '').toString().toUpperCase();\\n  } else {\\n    action = 'UNKNOWN';\\n  }\\n}\\n// P2-02: DLQ command\\nelse if (cmd === 'dlq') {\\n  const sub = (args[0] || 'list').toLowerCase();\\n  if (sub === 'list' || sub === 'ls') {\\n    action = 'DLQ_LIST';\\n    e.adminDlqLimit = parseInt(args[1] || '20', 10) || 20;\\n  } else if (sub === 'show' || sub === 'get') {\\n    action = 'DLQ_SHOW';\\n    e.adminDlqId = parseInt(args[1] || '0', 10) || 0;\\n  } else if (sub === 'replay' || sub === 'retry') {\\n    action = 'DLQ_REPLAY';\\n    e.adminDlqId = parseInt(args[1] || '0', 10) || 0;\\n  } else if (sub === 'drop' || sub === 'delete' || sub === 'rm') {\\n    action = 'DLQ_DROP';\\n    e.adminDlqId = parseInt(args[1] || '0', 10) || 0;\\n  } else {\\n    action = 'UNKNOWN';\\n  }\\n}\\n\\n// P2-04: STATS command\\nelse if (cmd === 'stats') {\\n  action = 'STATS';\\n  const sub = (args[0] || 'today').toLowerCase();\\n  e.adminStatsRange = sub;\\n  if (sub === 'week' || sub === '7d') {\\n    e.adminStatsDays = 7;\\n  } else if (sub === 'month' || sub === '30d') {\\n    e.adminStatsDays = 30;\\n  } else {\\n    e.adminStatsDays = 1;\\n  }\\n}\\n\\n\\n// P2-DZ-01: ORDER command\\nelse if (cmd === 'order' || cmd === 'orders' || cmd === 'cmd' || cmd === 'commande') {\\n  const sub = (args[0] || 'list').toLowerCase();\\n  if (sub === 'list' || sub === 'ls') {\\n    action = 'ORDER_LIST';\\n    e.adminOrderLimit = parseInt(args[1] || '20', 10) || 20;\\n    e.adminOrderStatus = (args[2] || '').toUpperCase() || null;\\n  } else if (sub === 'show' || sub === 'get' || sub === 'view') {\\n    action = 'ORDER_SHOW';\\n    e.adminOrderId = (args[1] || '').toString().trim();\\n  } else if (sub === 'noshow' || sub === 'no-show' || sub === 'ns') {\\n    action = 'ORDER_NOSHOW';\\n    e.adminOrderId = (args[1] || '').toString().trim();\\n  } else if (sub === 'cancel' || sub === 'annuler') {\\n    action = 'ORDER_CANCEL';\\n    e.adminOrderId = (args[1] || '').toString().trim();\\n    e.adminCancelReason = args.slice(2).join(' ') || 'Admin cancelled';\\n  } else if (sub === 'delivered' || sub === 'done' || sub === 'livré' || sub === 'livre') {\\n    action = 'ORDER_DELIVERED';\\n    e.adminOrderId = (args[1] || '').toString().trim();\\n  } else {\\n    action = 'UNKNOWN';\\n  }\\n}\\n// P2-DZ-01: CUSTOMER command\\nelse if (cmd === 'customer' || cmd === 'client' || cmd === 'user') {\\n  const sub = (args[0] || 'risk').toLowerCase();\\n  if (sub === 'risk' || sub === 'risque' || sub === 'score' || sub === 'profile') {\\n    action = 'CUSTOMER_RISK';\\n    e.adminCustomerId = (args[1] || '').toString().trim();\\n  } else if (sub === 'blacklist' || sub === 'block' || sub === 'ban') {\\n    action = 'CUSTOMER_BLACKLIST';\\n    e.adminCustomerId = (args[1] || '').toString().trim();\\n    e.adminBlacklistReason = args.slice(2).join(' ') || 'Admin blacklisted';\\n    e.adminBlacklistDays = 30;\\n  } else if (sub === 'unblock' || sub === 'unban' || sub === 'unblacklist') {\\n    action = 'CUSTOMER_UNBLOCK';\\n    e.adminCustomerId = (args[1] || '').toString().trim();\\n  } else {\\n    action = 'UNKNOWN';\\n  }\\n}\\n\\nelse action = 'UNKNOWN';\\n\\nreturn [{json:{\\n  ...e,\\n  adminAction: action,\\n  adminTicketId: ticketId,\\n  adminFilter: filter,\\n  adminMessage: message,\\n  adminUsage: usage(),\\n  adminTemplateKey: templateKey,\\n  adminTemplateLocale: templateLocale,\\n  adminTemplateContent: templateContent,\\n  adminTemplateVars: templateVars,\\n  adminTemplateVarsJson: JSON.stringify(templateVars),\\n  adminZoneOp: zoneOp,\\n  adminZoneWilaya: zoneWilaya,\\n  adminZoneCommune: zoneCommune,\\n  adminZoneFeeCents: zoneFee,\\n  adminZoneMinCents: zoneMin,\\n  adminZoneEtaMin: zoneEtaMin,\\n  adminZoneEtaMax: zoneEtaMax,\\n  adminZoneActive: zoneActive\\n}}];\\n"},"id":"f146c550-0219-4ecf-84d8-24d5a7b64ec0","name":"A5 - Parse Intent","type":"n8n-nodes-base.code","typeVersion":2,"position":[-120,0]},{"parameters":{"conditions":{"string":[{"value1":"={{$json.adminAction}}","operation":"equal","value2":"UNKNOWN"}]}},"id":"8b2e124f-52f0-40db-b34c-e2bcc9d16f1a","name":"B6 - Is UNKNOWN?","type":"n8n-nodes-base.if","typeVersion":2,"position":[120,20]},{"parameters":{"language":"javascript","jsCode":"return [{json:{...$json, adminReplyText: '❓ Commande inconnue. Tape !help'}}];"},"id":"a8cbebad-e6cc-4249-9081-325b47f96631","name":"B6 - Unknown","type":"n8n-nodes-base.code","typeVersion":2,"position":[320,20]},{"parameters":{"conditions":{"string":[{"value1":"={{$json.adminAction}}","operation":"equal","value2":"HELP"}]}},"id":"8a74cc9b-b848-4e62-87c4-4dbb4eced951","name":"B1 - Is HELP?","type":"n8n-nodes-base.if","typeVersion":2,"position":[120,0]},{"parameters":{"language":"javascript","jsCode":"return [{json:{...$json, adminReplyText: $json.adminUsage}}];"},"id":"82979ea2-b46a-406a-877f-f2a80af593bd","name":"B1a - Reply HELP","type":"n8n-nodes-base.code","typeVersion":2,"position":[320,-120]},{"parameters":{"conditions":{"string":[{"value1":"={{$json.adminAction}}","operation":"equal","value2":"TICKETS"}]}},"id":"d00f074e-816b-4f04-a481-f15ea5d99c7a","name":"B2 - Is TICKETS?","type":"n8n-nodes-base.if","typeVersion":2,"position":[120,140]},{"parameters":{"operation":"executeQuery","query":"SELECT ticket_id, status, reason_code, created_at, customer_user_id FROM support_tickets WHERE restaurant_id=$1 AND ( ($2='all') OR status IN ('OPEN','ASSIGNED')) ORDER BY created_at DESC LIMIT 10;","additionalFields":{"queryParams":"={{[$json.restaurantId, ($json.adminFilter||'open')]}}"}},"id":"80a43ece-8ee3-49bc-9ea2-c7d8d4e1f5eb","name":"B2a - List Tickets (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[320,140]},{"parameters":{"language":"javascript","jsCode":"const rows = ($json.data || []);\\nif (!rows.length) {\\n  return [{json:{...$json, adminReplyText:'✅ Aucun ticket.'}}];\\n}\\nlet out = '*Tickets*\\\\n';\\nfor (const r of rows) {\\n  const id = r.ticket_id;\\n  const st = r.status;\\n  const reason = r.reason_code;\\n  const cust = r.customer_user_id;\\n  out += `#${id} — ${st} — ${reason} — user:${cust}\\\\n`;\\n}\\nout += '\\\\nActions: !take <id> | !reply <id> <msg> | !close <id>';\\nreturn [{json:{...$json, adminReplyText: out}}];"},"id":"bdfe697f-7f33-4114-9549-d014828214a3","name":"B2b - Format Tickets","type":"n8n-nodes-base.code","typeVersion":2,"position":[520,140]},{"parameters":{"conditions":{"string":[{"value1":"={{$json.adminAction}}","operation":"equal","value2":"TAKE"}]}},"id":"6d81cc1e-197d-4b92-acfd-ed9c540c7eb6","name":"B3 - Is TAKE?","type":"n8n-nodes-base.if","typeVersion":2,"position":[120,280]},{"parameters":{"operation":"executeQuery","query":"WITH t AS (UPDATE support_tickets SET status='ASSIGNED', updated_at=now() WHERE ticket_id=$1 AND restaurant_id=$2 AND status IN ('OPEN','ASSIGNED') RETURNING ticket_id, status), a AS (INSERT INTO support_assignments(ticket_id, admin_user_id) SELECT $1,$3 WHERE EXISTS (SELECT 1 FROM t) RETURNING id) SELECT (SELECT ticket_id FROM t) AS ticket_id;","additionalFields":{"queryParams":"={{[$json.adminTicketId, $json.restaurantId, $json.userId]}}"}},"id":"e1c80492-e72d-4e0f-9554-fa497f2cf295","name":"B3a - Take Ticket (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[320,280]},{"parameters":{"language":"javascript","jsCode":"const ok = ($json.data && $json.data[0] && $json.data[0].ticket_id); return [{json:{...$json, adminReplyText: ok ? ('✅ Ticket #' + ok + ' pris.') : '⚠️ Ticket introuvable.'}}];"},"id":"06d4b8ec-5988-44bf-98dc-913645979a53","name":"B3b - Format Take","type":"n8n-nodes-base.code","typeVersion":2,"position":[520,280]},{"parameters":{"conditions":{"string":[{"value1":"={{$json.adminAction}}","operation":"equal","value2":"CLOSE"}]}},"id":"53189cc4-7a9f-4f7f-a9a6-34a6953b2149","name":"B4 - Is CLOSE?","type":"n8n-nodes-base.if","typeVersion":2,"position":[120,420]},{"parameters":{"operation":"executeQuery","query":"UPDATE support_tickets SET status='CLOSED', closed_at=now(), updated_at=now() WHERE ticket_id=$1 AND restaurant_id=$2 RETURNING ticket_id;","additionalFields":{"queryParams":"={{[$json.adminTicketId, $json.restaurantId]}}"}},"id":"10d59a54-034e-422b-af43-3a22eeff7ed5","name":"B4a - Close Ticket (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[320,420]},{"parameters":{"language":"javascript","jsCode":"const ok = ($json.data && $json.data[0] && $json.data[0].ticket_id); return [{json:{...$json, adminReplyText: ok ? ('✅ Ticket #' + ok + ' clôturé.') : '⚠️ Ticket introuvable.'}}];"},"id":"d24a9ab3-a977-4d3b-b5d6-4597e35bb712","name":"B4b - Format Close","type":"n8n-nodes-base.code","typeVersion":2,"position":[520,420]},{"parameters":{"conditions":{"string":[{"value1":"={{$json.adminAction}}","operation":"equal","value2":"REPLY"}]}},"id":"5275e076-fe11-4915-afeb-04bb97edd4c9","name":"B5 - Is REPLY?","type":"n8n-nodes-base.if","typeVersion":2,"position":[120,560]},{"parameters":{"operation":"executeQuery","query":"SELECT ticket_id, tenant_id, restaurant_id, channel, conversation_key, customer_user_id, status FROM support_tickets WHERE ticket_id=$1 AND restaurant_id=$2 LIMIT 1;","additionalFields":{"queryParams":"={{[$json.adminTicketId, $json.restaurantId]}}"}},"id":"518d4c70-71ed-41bb-adae-25f63dcada61","name":"B5a - Load Ticket (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[320,560]},{"parameters":{"operation":"executeQuery","query":"INSERT INTO support_ticket_messages(ticket_id, direction, from_user_id, to_user_id, body_text, meta_json) VALUES ($1,'OUTBOUND',$2,$3,$4,$5::jsonb) RETURNING id;","additionalFields":{"queryParams":"={{[($json.data && $json.data[0] ? $json.data[0].ticket_id : 0), $json.userId, ($json.data && $json.data[0] ? $json.data[0].customer_user_id : ''), ($json.adminMessage||''), JSON.stringify({source:'admin_wa_console'})]}}"}},"id":"8a5c9470-2fb3-442e-a690-5c14d64b5297","name":"B5b - Log Message (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[520,560]},{"parameters":{"language":"javascript","jsCode":"const e = $json;\\nconst row = (e.data && e.data[0]) ? e.data[0] : null;\\nif (!row || !e.adminMessage) {\\n  return [{json:{...e, customerOutbox: null, adminReplyText: '⚠️ Utilisation: !reply <ticket_id> <message>'}}];\\n}\\nconst dedupe = `support_reply:${row.ticket_id}:${e.inbound_message_id || e.message?.id || Date.now()}`;\\nconst payload = {\\n  channel: 'whatsapp',\\n  to_user_id: row.customer_user_id,\\n  conversation_key: row.conversation_key,\\n  text: e.adminMessage\\n};\\nreturn [{json:{\\n  ...e,\\n  customerOutbox: {\\n    tenant_id: row.tenant_id,\\n    restaurant_id: row.restaurant_id,\\n    channel: 'whatsapp',\\n    conversation_key: row.conversation_key,\\n    user_id: row.customer_user_id,\\n    template_key: 'TEXT',\\n    locale: 'fr',\\n    payload_json: payload,\\n    dedupe_key: dedupe\\n  },\\n  adminReplyText: `✅ Envoyé au client (ticket #${row.ticket_id}).`\\n}}];"},"id":"33e89e1f-da26-4f22-aff4-bc689ae1eacf","name":"B5c - Build Customer Outbox","type":"n8n-nodes-base.code","typeVersion":2,"position":[720,560]},{"parameters":{"operation":"executeQuery","query":"INSERT INTO outbound_messages(tenant_id, restaurant_id, channel, conversation_key, user_id, template_key, locale, payload_json, outbox_dedupe_key, status) VALUES ($1,$2,$3,$4,$5,$6,$7,$8::jsonb,$9,'PENDING') ON CONFLICT (outbox_dedupe_key) DO NOTHING;","additionalFields":{"queryParams":"={{[$json.customerOutbox.tenant_id, $json.customerOutbox.restaurant_id, $json.customerOutbox.channel, $json.customerOutbox.conversation_key, $json.customerOutbox.user_id, $json.customerOutbox.template_key, $json.customerOutbox.locale, JSON.stringify($json.customerOutbox.payload_json), $json.customerOutbox.dedupe_key]}}"}},"id":"ebea9c9f-c754-4b27-9e50-599af6d1b7cc","name":"B5d - Enqueue Customer Outbox (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[920,560]},{"parameters":{"language":"javascript","jsCode":"const crypto = require('crypto');\\nconst e = $json;\\nconst txt = (e.adminReplyText || '').toString();\\nconst adminConv = `t:${e.tenantId}:r:${e.restaurantId}:whatsapp:${e.userId}`;\\nconst dedupe = `admin_console:${e.userId}:${e.inbound_message_id || e.message?.id || crypto.randomUUID()}`;\\nconst payload = { channel: 'whatsapp', to_user_id: e.userId, conversation_key: adminConv, text: txt };\\nreturn [{json:{...e, adminOutbox:{\\n  tenant_id: e.tenantId,\\n  restaurant_id: e.restaurantId,\\n  channel: 'whatsapp',\\n  conversation_key: adminConv,\\n  user_id: e.userId,\\n  template_key: 'TEXT',\\n  locale: (e.adminConsole?.locale || 'fr'),\\n  payload_json: payload,\\n  dedupe_key: dedupe\\n}}}];"},"id":"0e59f7a4-fd82-4bcc-9667-f9b64ff8ddf4","name":"O0 - Build Admin Outbox","type":"n8n-nodes-base.code","typeVersion":2,"position":[560,20]},{"parameters":{"operation":"executeQuery","query":"INSERT INTO outbound_messages(tenant_id, restaurant_id, channel, conversation_key, user_id, template_key, locale, payload_json, outbox_dedupe_key, status) VALUES ($1,$2,$3,$4,$5,$6,$7,$8::jsonb,$9,'PENDING') ON CONFLICT (outbox_dedupe_key) DO NOTHING;","additionalFields":{"queryParams":"={{[$json.adminOutbox.tenant_id, $json.adminOutbox.restaurant_id, $json.adminOutbox.channel, $json.adminOutbox.conversation_key, $json.adminOutbox.user_id, $json.adminOutbox.template_key, $json.adminOutbox.locale, JSON.stringify($json.adminOutbox.payload_json), $json.adminOutbox.dedupe_key]}}"}},"id":"840153cc-efcf-4ca3-970f-d39a03a2d325","name":"O1 - Enqueue Admin Outbox (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[760,20]},{"parameters":{"conditions":{"string":[{"value1":"={{$json.adminAction}}","operation":"equal","value2":"TEMPLATE_GET"}]}},"id":"7a87afc9-dd15-483f-8dcb-fdd15a07e1e8","name":"B7 - Is TEMPLATE_GET?","type":"n8n-nodes-base.if","typeVersion":2,"position":[120,340]},{"parameters":{"operation":"executeQuery","query":"SELECT tenant_id, key, locale, content, variables\\nFROM public.message_templates\\nWHERE (tenant_id=$1 OR tenant_id='_GLOBAL')\\n  AND key=$2 AND locale=lower($3)\\nORDER BY CASE WHEN tenant_id=$1 THEN 0 ELSE 1 END\\nLIMIT 1;","additionalFields":{"queryParams":"={{[$json.tenantId, $json.adminTemplateKey, $json.adminTemplateLocale]}}"}},"id":"90084aeb-596b-42ed-ab9a-d31f4fa54c9f","name":"B7a - Template Get (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[320,340]},{"parameters":{"language":"javascript","jsCode":"const rows = ($json.data || []);\\nconst key = ($json.adminTemplateKey || '').toString();\\nconst loc = ($json.adminTemplateLocale || 'fr').toString();\\nif (!rows.length) {\\n  return [{json:{...$json, adminReplyText: `❌ Aucun template trouvé pour *${key}* (${loc}).\\n➡️ Utilise: !template set ${key} ${loc} <contenu>`}}];\\n}\\nconst r = rows[0];\\nconst from = (r.tenant_id === '_GLOBAL') ? '_GLOBAL' : 'tenant';\\nconst vars = Array.isArray(r.variables) ? r.variables : (r.variables || []);\\nlet out = `🧩 *Template* ${r.key} (${r.locale}) [source: ${from}]\\n`;\\nout += `Vars: ${(vars && vars.length) ? vars.join(', ') : '(none)'}\\n\\n`;\\nout += r.content;\\nreturn [{json:{...$json, adminReplyText: out}}];"},"id":"a5ac0e79-b095-4698-8cf1-fa29ff994f77","name":"B7b - Format Template Get","type":"n8n-nodes-base.code","typeVersion":2,"position":[520,340]},{"parameters":{"conditions":{"string":[{"value1":"={{$json.adminAction}}","operation":"equal","value2":"TEMPLATE_SET"}]}},"id":"67c986a2-064d-4273-9612-15107ed03566","name":"B8 - Is TEMPLATE_SET?","type":"n8n-nodes-base.if","typeVersion":2,"position":[120,420]},{"parameters":{"operation":"executeQuery","query":"INSERT INTO public.message_templates(tenant_id, key, locale, content, variables)\\nVALUES ($1,$2,lower($3),$4, COALESCE((SELECT variables FROM public.message_templates WHERE tenant_id=$1 AND key=$2 AND locale=lower($3)), '[]'::jsonb))\\nON CONFLICT (tenant_id, key, locale) DO UPDATE\\n  SET content=EXCLUDED.content, updated_at=now()\\nRETURNING tenant_id, key, locale, content, variables;","additionalFields":{"queryParams":"={{[$json.tenantId, $json.adminTemplateKey, $json.adminTemplateLocale, $json.adminTemplateContent]}}"}},"id":"289806f5-8308-436f-8ec3-0ae25310328d","name":"B8a - Template Set (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[320,420]},{"parameters":{"language":"javascript","jsCode":"const rows = ($json.data || []);\\nif (!rows.length) {\\n  return [{json:{...$json, adminReplyText:'❌ Impossible de sauvegarder le template.'}}];\\n}\\nconst r = rows[0];\\nconst vars = Array.isArray(r.variables) ? r.variables : (r.variables || []);\\nlet out = `✅ Template sauvegardé: *${r.key}* (${r.locale}) [tenant]`;\\nout += `\\nVars: ${(vars && vars.length) ? vars.join(', ') : '(none)'}\\n`;\\nout += `\\nAstuce: pour définir les variables autorisées: !template vars ${r.key} ${r.locale} order_id,eta`;\\nreturn [{json:{...$json, adminReplyText: out}}];"},"id":"4239bb4d-8b60-43eb-8b18-92b1991740a6","name":"B8b - Format Template Set","type":"n8n-nodes-base.code","typeVersion":2,"position":[520,420]},{"parameters":{"conditions":{"string":[{"value1":"={{$json.adminAction}}","operation":"equal","value2":"TEMPLATE_VARS"}]}},"id":"41c9cebd-a063-49c0-ae96-4ffd244c192d","name":"B9 - Is TEMPLATE_VARS?","type":"n8n-nodes-base.if","typeVersion":2,"position":[120,500]},{"parameters":{"operation":"executeQuery","query":"INSERT INTO public.message_templates(tenant_id, key, locale, content, variables)\\nVALUES ($1,$2,lower($3), COALESCE((SELECT content FROM public.message_templates WHERE tenant_id=$1 AND key=$2 AND locale=lower($3)), ''), $4::jsonb)\\nON CONFLICT (tenant_id, key, locale) DO UPDATE\\n  SET variables=EXCLUDED.variables, updated_at=now()\\nRETURNING tenant_id, key, locale, content, variables;","additionalFields":{"queryParams":"={{[$json.tenantId, $json.adminTemplateKey, $json.adminTemplateLocale, $json.adminTemplateVarsJson]}}"}},"id":"4f778a36-bd42-4a99-b7e6-02fb63c607a8","name":"B9a - Template Vars (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[320,500]},{"parameters":{"language":"javascript","jsCode":"const rows = ($json.data || []);\\nif (!rows.length) {\\n  return [{json:{...$json, adminReplyText:'❌ Impossible de sauvegarder les variables.'}}];\\n}\\nconst r = rows[0];\\nconst vars = Array.isArray(r.variables) ? r.variables : (r.variables || []);\\nlet out = `✅ Variables sauvegardées: *${r.key}* (${r.locale})`;\\nout += `\\nVars: ${(vars && vars.length) ? vars.join(', ') : '(none)'}`;\\nout += `\\n\\nRappel: seules ces variables seront rendues, les autres placeholders seront supprimés.`;\\nreturn [{json:{...$json, adminReplyText: out}}];"},"id":"9b38fae0-df0e-4a03-9a9b-e818ce664bc6","name":"B9b - Format Template Vars","type":"n8n-nodes-base.code","typeVersion":2,"position":[520,500]},{"parameters":{"conditions":{"string":[{"value1":"={{$json.adminAction}}","operation":"equal","value2":"ZONE_LIST"}]}},"id":"C1_IS_ZONE_LIST","name":"C1 - Is ZONE_LIST?","type":"n8n-nodes-base.if","typeVersion":2,"position":[860,980]},{"parameters":{"conditions":{"string":[{"value1":"={{$json.adminAction}}","operation":"equal","value2":"ZONE_SET"}]}},"id":"C2_IS_ZONE_SET","name":"C2 - Is ZONE_SET?","type":"n8n-nodes-base.if","typeVersion":2,"position":[860,1140]},{"parameters":{"conditions":{"string":[{"value1":"={{$json.adminAction}}","operation":"equal","value2":"ZONE_DELETE"}]}},"id":"C3_IS_ZONE_DELETE","name":"C3 - Is ZONE_DELETE?","type":"n8n-nodes-base.if","typeVersion":2,"position":[860,1300]},{"parameters":{"operation":"executeQuery","query":"SELECT zone_id, wilaya, commune, fee_base_cents, min_order_cents, eta_min, eta_max, is_active\\nFROM public.delivery_zones\\nWHERE restaurant_id = $1\\nORDER BY lower(wilaya), lower(commune)\\nLIMIT 50;","additionalFields":{"queryParams":"={{[$json.restaurantId]}}"}},"id":"C1A_ZONE_LIST_DB","name":"C1a - Zone List (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[1090,980]},{"parameters":{"jsCode":"const e = $json;\\nconst loc = (e.adminConsole?.locale || 'fr');\\nconst rows = $items(\\"C1a - Zone List (DB)\\").map(i => i.json);\\nlet txt = '';\\nif (!rows.length) {\\n  txt = (loc==='ar') ? 'لا توجد مناطق توصيل مُسجلة.' : 'Aucune zone de livraison enregistrée.';\\n} else {\\n  txt = (loc==='ar') ? '📍 مناطق التوصيل:\\\\n' : '📍 Zones de livraison :\\\\n';\\n  for (const z of rows.slice(0, 25)) {\\n    const active = z.is_active ? (loc==='ar'?'✅ مفعّل':'✅ actif') : (loc==='ar'?'⛔ غير مفعّل':'⛔ inactif');\\n    txt += `- ${z.wilaya} / ${z.commune} | fee=${z.fee_base_cents} | min=${z.min_order_cents} | ETA=${z.eta_min}-${z.eta_max} | ${active}\\\\n`;\\n  }\\n}\\ne.adminReplyText = txt.trim();\\nreturn [{json:e}];"},"id":"C1B_FORMAT_ZONE_LIST","name":"C1b - Format Zone List","type":"n8n-nodes-base.code","typeVersion":2,"position":[1310,980]},{"parameters":{"operation":"executeQuery","query":"WITH inp AS (\\n  SELECT\\n    $1::uuid AS restaurant_id,\\n    NULLIF(trim($2::text),'') AS wilaya,\\n    NULLIF(trim($3::text),'') AS commune,\\n    GREATEST(COALESCE($4::int,0),0) AS fee_base_cents,\\n    GREATEST(COALESCE($5::int,0),0) AS min_order_cents,\\n    GREATEST(COALESCE($6::int,0),0) AS eta_min,\\n    GREATEST(COALESCE($7::int,0),0) AS eta_max,\\n    COALESCE($8::boolean,true) AS is_active\\n), u AS (\\n  UPDATE public.delivery_zones z\\n  SET fee_base_cents=inp.fee_base_cents,\\n      min_order_cents=inp.min_order_cents,\\n      eta_min=inp.eta_min,\\n      eta_max=GREATEST(inp.eta_max, inp.eta_min),\\n      is_active=inp.is_active,\\n      updated_at=now()\\n  FROM inp\\n  WHERE z.restaurant_id=inp.restaurant_id\\n    AND lower(z.wilaya)=lower(inp.wilaya)\\n    AND lower(z.commune)=lower(inp.commune)\\n  RETURNING z.zone_id\\n), i AS (\\n  INSERT INTO public.delivery_zones(restaurant_id,wilaya,commune,fee_base_cents,min_order_cents,eta_min,eta_max,is_active)\\n  SELECT inp.restaurant_id, inp.wilaya, inp.commune, inp.fee_base_cents, inp.min_order_cents, inp.eta_min, GREATEST(inp.eta_max, inp.eta_min), inp.is_active\\n  FROM inp\\n  WHERE inp.wilaya IS NOT NULL AND inp.commune IS NOT NULL\\n    AND NOT EXISTS (SELECT 1 FROM u)\\n  RETURNING zone_id\\n)\\nSELECT COALESCE((SELECT zone_id FROM u), (SELECT zone_id FROM i)) AS zone_id;","additionalFields":{"queryParams":"={{[$json.restaurantId, $json.adminZoneWilaya, $json.adminZoneCommune, $json.adminZoneFeeCents, $json.adminZoneMinCents, $json.adminZoneEtaMin, $json.adminZoneEtaMax, $json.adminZoneActive]}}"}},"id":"C2A_ZONE_UPSERT_DB","name":"C2a - Zone Upsert (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[1090,1140]},{"parameters":{"operation":"executeQuery","query":"SELECT insert_admin_wa_audit($1::uuid,$2::uuid,$3::text,$4::text,$5::text,$6::text,$7::text,$8::jsonb,NULL,true,NULL) AS audit_id;","additionalFields":{"queryParams":"={{[$json.tenantId, $json.restaurantId, $json.userId, ($json.rbac?.role || 'admin'), ($items('C2a - Zone Upsert (DB)')[0].json.zone_id ? 'zone_update' : 'zone_create'), 'zone', String($items('C2a - Zone Upsert (DB)')[0].json.zone_id || ''), JSON.stringify({wilaya:$json.adminZoneWilaya, commune:$json.adminZoneCommune, fee:$json.adminZoneFeeCents, min:$json.adminZoneMinCents, etaMin:$json.adminZoneEtaMin, etaMax:$json.adminZoneEtaMax, active:$json.adminZoneActive})]}}"}},"id":"C2B_AUDIT_ZONE_UPSERT","name":"C2b - Audit Zone Upsert (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[1310,1140]},{"parameters":{"jsCode":"const e = $json;\\nconst loc = (e.adminConsole?.locale || 'fr');\\nconst zoneId = $items(\\"C2a - Zone Upsert (DB)\\")[0]?.json?.zone_id;\\nconst active = e.adminZoneActive ? (loc==='ar'?'مفعّل':'actif') : (loc==='ar'?'غير مفعّل':'inactif');\\nconst txt = (loc==='ar')\\n  ? `✅ تم حفظ منطقة التوصيل.\\\\n${e.adminZoneWilaya} / ${e.adminZoneCommune}\\\\nfee=${e.adminZoneFeeCents} min=${e.adminZoneMinCents} ETA=${e.adminZoneEtaMin}-${e.adminZoneEtaMax} (${active})\\\\nzone_id=${zoneId}`\\n  : `✅ Zone enregistrée.\\\\n${e.adminZoneWilaya} / ${e.adminZoneCommune}\\\\nfee=${e.adminZoneFeeCents} min=${e.adminZoneMinCents} ETA=${e.adminZoneEtaMin}-${e.adminZoneEtaMax} (${active})\\\\nzone_id=${zoneId}`;\\ne.adminReplyText = txt.trim();\\nreturn [{json:e}];"},"id":"C2C_FORMAT_ZONE_UPSERT","name":"C2c - Format Zone Upsert","type":"n8n-nodes-base.code","typeVersion":2,"position":[1510,1140]},{"parameters":{"operation":"executeQuery","query":"DELETE FROM public.delivery_zones\\nWHERE restaurant_id=$1 AND lower(wilaya)=lower($2) AND lower(commune)=lower($3)\\nRETURNING zone_id;","additionalFields":{"queryParams":"={{[$json.restaurantId, $json.adminZoneWilaya, $json.adminZoneCommune]}}"}},"id":"C3A_ZONE_DELETE_DB","name":"C3a - Zone Delete (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[1090,1300]},{"parameters":{"operation":"executeQuery","query":"SELECT insert_admin_wa_audit($1::uuid,$2::uuid,$3::text,$4::text,'zone_delete','zone',$5::text,$6::text,$7::jsonb,NULL,true,NULL) AS audit_id;","additionalFields":{"queryParams":"={{[$json.tenantId, $json.restaurantId, $json.userId, ($json.rbac?.role || 'admin'), String($items('C3a - Zone Delete (DB)')[0].json.zone_id || ''), String($json.adminConsole?.raw || '').slice(0,200), JSON.stringify({wilaya:$json.adminZoneWilaya, commune:$json.adminZoneCommune})]}}"}},"id":"C3B_AUDIT_ZONE_DELETE","name":"C3b - Audit Zone Delete (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[1310,1300]},{"parameters":{"jsCode":"const e = $json;\\nconst loc = (e.adminConsole?.locale || 'fr');\\nconst zoneId = $items(\\"C3a - Zone Delete (DB)\\")[0]?.json?.zone_id;\\nlet txt = '';\\nif (!zoneId) {\\n  txt = (loc==='ar')\\n    ? `⚠️ لم يتم العثور على المنطقة: ${e.adminZoneWilaya} / ${e.adminZoneCommune}`\\n    : `⚠️ Zone introuvable : ${e.adminZoneWilaya} / ${e.adminZoneCommune}`;\\n} else {\\n  txt = (loc==='ar')\\n    ? `🗑️ تم حذف منطقة التوصيل.\\\\n${e.adminZoneWilaya} / ${e.adminZoneCommune}\\\\nzone_id=${zoneId}`\\n    : `🗑️ Zone supprimée.\\\\n${e.adminZoneWilaya} / ${e.adminZoneCommune}\\\\nzone_id=${zoneId}`;\\n}\\ne.adminReplyText = txt.trim();\\nreturn [{json:e}];"},"id":"C3C_FORMAT_ZONE_DELETE","name":"C3c - Format Zone Delete","type":"n8n-nodes-base.code","typeVersion":2,"position":[1510,1300]},{"parameters":{"conditions":{"string":[{"value1":"={{$json.adminAction}}","operation":"equal","value2":"STATUS"}]}},"id":"D1_IS_STATUS","name":"D1 - Is STATUS?","type":"n8n-nodes-base.if","typeVersion":2,"position":[120,700]},{"parameters":{"operation":"executeQuery","query":"SELECT get_system_status() AS status;","additionalFields":{}},"id":"D1A_STATUS_DB","name":"D1a - Get Status (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[320,700]},{"parameters":{"language":"javascript","jsCode":"const e = $json;\\nconst statusData = e.data?.[0]?.status || {};\\nconst ts = statusData.timestamp || new Date().toISOString();\\nconst db = statusData.database || {};\\nconst counts = statusData.counts || {};\\nconst flags = statusData.flags || {};\\n\\nlet txt = '*System Status*\\\\n';\\ntxt += '─────────────\\\\n';\\ntxt += `⏰ ${ts}\\\\n\\\\n`;\\n\\ntxt += '*Database*\\\\n';\\ntxt += `  Connected: ${db.connected ? '✅' : '❌'}\\\\n\\\\n`;\\n\\ntxt += '*Counts*\\\\n';\\ntxt += `  Pending outbound: ${counts.pending_outbound || 0}\\\\n`;\\ntxt += `  DLQ messages: ${counts.dlq_messages || 0}\\\\n`;\\ntxt += `  Active tickets: ${counts.active_tickets || 0}\\\\n`;\\ntxt += `  Conversations (24h): ${counts.conversations_24h || 0}\\\\n\\\\n`;\\n\\ntxt += '*Flags*\\\\n';\\nfor (const [k, v] of Object.entries(flags)) {\\n  const icon = (v === 'true' || v === true) ? '🟢' : (v === 'false' || v === false) ? '🔴' : '⚪';\\n  txt += `  ${icon} ${k}: ${v}\\\\n`;\\n}\\n\\nreturn [{json:{...e, adminReplyText: txt.trim()}}];"},"id":"D1B_FORMAT_STATUS","name":"D1b - Format Status","type":"n8n-nodes-base.code","typeVersion":2,"position":[520,700]},{"parameters":{"conditions":{"string":[{"value1":"={{$json.adminAction}}","operation":"equal","value2":"FLAGS_LIST"}]}},"id":"D2_IS_FLAGS_LIST","name":"D2 - Is FLAGS_LIST?","type":"n8n-nodes-base.if","typeVersion":2,"position":[120,820]},{"parameters":{"operation":"executeQuery","query":"SELECT flag_key, flag_value, description, updated_at FROM system_flags ORDER BY flag_key;","additionalFields":{}},"id":"D2A_FLAGS_LIST_DB","name":"D2a - Get Flags (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[320,820]},{"parameters":{"language":"javascript","jsCode":"const e = $json;\\nconst rows = e.data || [];\\nif (!rows.length) {\\n  return [{json:{...e, adminReplyText: 'No system flags configured.'}}];\\n}\\nlet txt = '*System Flags*\\\\n';\\ntxt += '─────────────\\\\n';\\nfor (const r of rows) {\\n  const icon = (r.flag_value === 'true') ? '🟢' : (r.flag_value === 'false') ? '🔴' : '⚪';\\n  txt += `${icon} *${r.flag_key}*: ${r.flag_value}\\\\n`;\\n  if (r.description) txt += `   _${r.description}_\\\\n`;\\n}\\ntxt += '\\\\n➡️ !flags set <KEY> <VALUE>';\\nreturn [{json:{...e, adminReplyText: txt.trim()}}];"},"id":"D2B_FORMAT_FLAGS_LIST","name":"D2b - Format Flags List","type":"n8n-nodes-base.code","typeVersion":2,"position":[520,820]},{"parameters":{"conditions":{"string":[{"value1":"={{$json.adminAction}}","operation":"equal","value2":"FLAGS_SET"}]}},"id":"D3_IS_FLAGS_SET","name":"D3 - Is FLAGS_SET?","type":"n8n-nodes-base.if","typeVersion":2,"position":[120,940]},{"parameters":{"operation":"executeQuery","query":"UPDATE system_flags SET flag_value=$2, updated_at=now(), updated_by=$3 WHERE flag_key=$1 RETURNING flag_key, flag_value;","additionalFields":{"queryParams":"={{[$json.adminFlagKey, $json.adminFlagValue, $json.userId]}}"}},"id":"D3A_FLAGS_SET_DB","name":"D3a - Set Flag (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[320,940]},{"parameters":{"language":"javascript","jsCode":"const e = $json;\\nconst rows = e.data || [];\\nif (!rows.length) {\\n  return [{json:{...e, adminReplyText: '❌ Flag not found: ' + (e.adminFlagKey || '?')}}];\\n}\\nconst r = rows[0];\\nconst icon = (r.flag_value === 'true') ? '🟢' : (r.flag_value === 'false') ? '🔴' : '⚪';\\nreturn [{json:{...e, adminReplyText: `✅ Flag updated\\\\n${icon} *${r.flag_key}* = ${r.flag_value}`}}];"},"id":"D3B_FORMAT_FLAGS_SET","name":"D3b - Format Flag Set","type":"n8n-nodes-base.code","typeVersion":2,"position":[520,940]},{"parameters":{"conditions":{"string":[{"value1":"={{$json.adminAction}}","operation":"equal","value2":"DLQ_LIST"}]}},"id":"D4_IS_DLQ_LIST","name":"D4 - Is DLQ_LIST?","type":"n8n-nodes-base.if","typeVersion":2,"position":[120,1060]},{"parameters":{"operation":"executeQuery","query":"SELECT * FROM get_dlq_messages($1, 0);","additionalFields":{"queryParams":"={{[$json.adminDlqLimit || 20]}}"}},"id":"D4A_DLQ_LIST_DB","name":"D4a - Get DLQ List (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[320,1060]},{"parameters":{"language":"javascript","jsCode":"const e = $json;\\nconst rows = e.data || [];\\nif (!rows.length) {\\n  return [{json:{...e, adminReplyText: '✅ DLQ is empty. No failed messages.'}}];\\n}\\nlet txt = '*DLQ Messages (' + rows.length + ')*\\\\n';\\ntxt += '─────────────\\\\n';\\nfor (const r of rows.slice(0, 15)) {\\n  const age = r.created_at ? new Date(r.created_at).toISOString().slice(0,16).replace('T',' ') : '?';\\n  txt += `#${r.outbound_id} | ${r.channel} | ${r.user_id?.slice(0,12) || '?'} | att:${r.attempts}\\\\n`;\\n  txt += `   err: ${(r.last_error || '?').slice(0,50)}\\\\n`;\\n}\\nif (rows.length > 15) txt += `... and ${rows.length - 15} more\\\\n`;\\ntxt += '\\\\n➡️ !dlq show <id> | !dlq replay <id> | !dlq drop <id>';\\nreturn [{json:{...e, adminReplyText: txt.trim()}}];"},"id":"D4B_FORMAT_DLQ_LIST","name":"D4b - Format DLQ List","type":"n8n-nodes-base.code","typeVersion":2,"position":[520,1060]},{"parameters":{"conditions":{"string":[{"value1":"={{$json.adminAction}}","operation":"equal","value2":"DLQ_SHOW"}]}},"id":"D5_IS_DLQ_SHOW","name":"D5 - Is DLQ_SHOW?","type":"n8n-nodes-base.if","typeVersion":2,"position":[120,1180]},{"parameters":{"operation":"executeQuery","query":"SELECT outbound_id, channel, user_id, restaurant_id, status, attempts, last_error, created_at, correlation_id, payload_json FROM outbound_messages WHERE outbound_id=$1 AND status='DLQ';","additionalFields":{"queryParams":"={{[$json.adminDlqId]}}"}},"id":"D5A_DLQ_SHOW_DB","name":"D5a - Get DLQ Item (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[320,1180]},{"parameters":{"language":"javascript","jsCode":"const e = $json;\\nconst rows = e.data || [];\\nif (!rows.length) {\\n  return [{json:{...e, adminReplyText: '❌ DLQ message not found: #' + (e.adminDlqId || '?')}}];\\n}\\nconst r = rows[0];\\nlet txt = '*DLQ Message #' + r.outbound_id + '*\\\\n';\\ntxt += '─────────────\\\\n';\\ntxt += `Channel: ${r.channel}\\\\n`;\\ntxt += `User: ${r.user_id}\\\\n`;\\ntxt += `Attempts: ${r.attempts}\\\\n`;\\ntxt += `Created: ${r.created_at}\\\\n`;\\ntxt += `Correlation: ${r.correlation_id || '-'}\\\\n\\\\n`;\\ntxt += '*Last Error*\\\\n${r.last_error || '-'}\\\\n\\\\n`;\\ntxt += '*Payload*\\\\n';\\ntry {\\n  const p = typeof r.payload_json === 'string' ? JSON.parse(r.payload_json) : r.payload_json;\\n  txt += JSON.stringify(p, null, 2).slice(0, 500);\\n} catch { txt += String(r.payload_json).slice(0, 500); }\\ntxt += '\\\\n\\\\n➡️ !dlq replay ' + r.outbound_id + ' | !dlq drop ' + r.outbound_id;\\nreturn [{json:{...e, adminReplyText: txt.trim()}}];"},"id":"D5B_FORMAT_DLQ_SHOW","name":"D5b - Format DLQ Show","type":"n8n-nodes-base.code","typeVersion":2,"position":[520,1180]},{"parameters":{"conditions":{"string":[{"value1":"={{$json.adminAction}}","operation":"equal","value2":"DLQ_REPLAY"}]}},"id":"D6_IS_DLQ_REPLAY","name":"D6 - Is DLQ_REPLAY?","type":"n8n-nodes-base.if","typeVersion":2,"position":[120,1300]},{"parameters":{"operation":"executeQuery","query":"SELECT replay_dlq_message($1, $2) AS result;","additionalFields":{"queryParams":"={{[$json.adminDlqId, $json.userId]}}"}},"id":"D6A_DLQ_REPLAY_DB","name":"D6a - Replay DLQ (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[320,1300]},{"parameters":{"language":"javascript","jsCode":"const e = $json;\\nconst result = e.data?.[0]?.result || {};\\nif (!result.success) {\\n  return [{json:{...e, adminReplyText: '❌ Replay failed: ' + (result.error || 'Unknown error')}}];\\n}\\nreturn [{json:{...e, adminReplyText: '✅ Message #' + result.outbound_id + ' queued for retry.\\\\nNew status: ' + result.new_status}}];"},"id":"D6B_FORMAT_DLQ_REPLAY","name":"D6b - Format DLQ Replay","type":"n8n-nodes-base.code","typeVersion":2,"position":[520,1300]},{"parameters":{"conditions":{"string":[{"value1":"={{$json.adminAction}}","operation":"equal","value2":"DLQ_DROP"}]}},"id":"D7_IS_DLQ_DROP","name":"D7 - Is DLQ_DROP?","type":"n8n-nodes-base.if","typeVersion":2,"position":[120,1420]},{"parameters":{"operation":"executeQuery","query":"SELECT drop_dlq_message($1, $2) AS result;","additionalFields":{"queryParams":"={{[$json.adminDlqId, $json.userId]}}"}},"id":"D7A_DLQ_DROP_DB","name":"D7a - Drop DLQ (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[320,1420]},{"parameters":{"language":"javascript","jsCode":"const e = $json;\\nconst result = e.data?.[0]?.result || {};\\nif (!result.success) {\\n  return [{json:{...e, adminReplyText: '❌ Drop failed: ' + (result.error || 'Unknown error')}}];\\n}\\nreturn [{json:{...e, adminReplyText: '🗑️ Message #' + result.outbound_id + ' permanently dropped.\\\\nNew status: ' + result.new_status}}];"},"id":"D7B_FORMAT_DLQ_DROP","name":"D7b - Format DLQ Drop","type":"n8n-nodes-base.code","typeVersion":2,"position":[520,1420]},{"parameters":{"conditions":{"string":[{"value1":"={{$json.adminAction}}","operation":"equal","value2":"STATS"}]}},"id":"D8_IS_STATS","name":"D8 - Is STATS?","type":"n8n-nodes-base.if","typeVersion":2,"position":[120,1540]},{"parameters":{"operation":"executeQuery","query":"SELECT get_daily_stats(CURRENT_DATE) AS stats;","additionalFields":{}},"id":"D8A_STATS_DB","name":"D8a - Get Stats (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[320,1540]},{"parameters":{"language":"javascript","jsCode":"const e = $json;\\nconst statsData = e.data?.[0]?.stats || {};\\nconst date = statsData.date || new Date().toISOString().slice(0, 10);\\nconst inbound = statsData.inbound || {};\\nconst outbound = statsData.outbound || {};\\nconst errors = statsData.errors || {};\\nconst latency = statsData.latency || {};\\n\\nlet txt = '*Daily Stats (' + date + ')*\\\\n';\\ntxt += '═══════════════════════\\\\n\\\\n';\\n\\ntxt += '*Inbound Messages*\\\\n';\\ntxt += '  Total: ' + (inbound.total || 0) + '\\\\n';\\ntxt += '  WhatsApp: ' + (inbound.whatsapp || 0) + '\\\\n';\\ntxt += '  Instagram: ' + (inbound.instagram || 0) + '\\\\n';\\ntxt += '  Messenger: ' + (inbound.messenger || 0) + '\\\\n\\\\n';\\n\\ntxt += '*Outbound Messages*\\\\n';\\ntxt += '  Total: ' + (outbound.total || 0) + '\\\\n';\\ntxt += '  WhatsApp: ' + (outbound.whatsapp || 0) + '\\\\n';\\ntxt += '  Instagram: ' + (outbound.instagram || 0) + '\\\\n';\\ntxt += '  Messenger: ' + (outbound.messenger || 0) + '\\\\n\\\\n';\\n\\ntxt += '*Errors*\\\\n';\\ntxt += '  Total: ' + (errors.total || 0) + '\\\\n';\\ntxt += '  Auth: ' + (errors.auth || 0) + '\\\\n';\\ntxt += '  Validation: ' + (errors.validation || 0) + '\\\\n';\\ntxt += '  Outbound: ' + (errors.outbound || 0) + '\\\\n\\\\n';\\n\\nif (latency && latency.samples > 0) {\\n  txt += '*Latency*\\\\n';\\n  txt += '  Samples: ' + latency.samples + '\\\\n';\\n  txt += '  Avg: ' + (latency.avg_ms || 0) + 'ms\\\\n';\\n  txt += '  P50: ' + (latency.p50_ms || 0) + 'ms\\\\n';\\n  txt += '  P95: ' + (latency.p95_ms || 0) + 'ms\\\\n';\\n  txt += '  P99: ' + (latency.p99_ms || 0) + 'ms\\\\n';\\n  txt += '  Max: ' + (latency.max_ms || 0) + 'ms\\\\n';\\n} else {\\n  txt += '*Latency*\\\\n  No samples yet\\\\n';\\n}\\n\\ntxt += '\\\\n➡️ !stats [today|week|month]';\\n\\nreturn [{json:{...e, adminReplyText: txt.trim()}}];"},"id":"D8B_FORMAT_STATS","name":"D8b - Format Stats","type":"n8n-nodes-base.code","typeVersion":2,"position":[520,1540]},{"parameters":{"conditions":{"string":[{"value1":"={{$json.adminAction}}","operation":"equal","value2":"ORDER_LIST"}]}},"id":"ORDER_LIST_CHECK","name":"E1 - Is ORDER_LIST?","type":"n8n-nodes-base.if","typeVersion":2,"position":[120,1400]},{"parameters":{"operation":"executeQuery","query":"SELECT * FROM get_recent_orders($1, $2, $3);","additionalFields":{"queryParams":"={{[$json.restaurantId, $json.adminOrderLimit || 20, $json.adminOrderStatus || null]}}"}},"id":"ORDER_LIST_DB","name":"E1a - Get Orders (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[320,1400]},{"parameters":{"language":"javascript","jsCode":"const rows = $json.data || [];\\nif (rows.length === 0) {\\n  return [{json: {...$json, adminReplyText: '📋 Aucune commande trouvée.'}}];\\n}\\nconst lines = rows.slice(0, 20).map((r, i) => {\\n  const status = r.status || 'NEW';\\n  const pay = r.payment_status || 'PENDING';\\n  const emoji = status === 'DONE' ? '✅' : status === 'CANCELLED' ? '❌' : status === 'READY' ? '🔔' : '⏳';\\n  const total = ((r.total_cents || 0) / 100).toFixed(0);\\n  const id = (r.order_id || '').toString().slice(0, 8);\\n  return `${emoji} ${id} | ${r.user_id?.slice(-4) || '????'} | ${total} DA | ${status}/${pay}`;\\n});\\nconst reply = '*📋 Commandes récentes*\\\\n\\\\n' + lines.join('\\\\n') + '\\\\n\\\\n_!order show <id> pour détails_';\\nreturn [{json: {...$json, adminReplyText: reply}}];"},"id":"ORDER_LIST_FORMAT","name":"E1b - Format Order List","type":"n8n-nodes-base.code","typeVersion":2,"position":[520,1400]},{"parameters":{"conditions":{"string":[{"value1":"={{$json.adminAction}}","operation":"equal","value2":"ORDER_SHOW"}]}},"id":"ORDER_SHOW_CHECK","name":"E2 - Is ORDER_SHOW?","type":"n8n-nodes-base.if","typeVersion":2,"position":[120,1520]},{"parameters":{"operation":"executeQuery","query":"SELECT * FROM get_order_details($1::uuid);","additionalFields":{"queryParams":"={{[$json.adminOrderId]}}"}},"id":"ORDER_SHOW_DB","name":"E2a - Get Order (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[320,1520]},{"parameters":{"language":"javascript","jsCode":"const r = ($json.data || [])[0];\\nif (!r) {\\n  return [{json: {...$json, adminReplyText: '❌ Commande non trouvée: ' + ($json.adminOrderId || 'ID manquant')}}];\\n}\\nconst total = ((r.total_cents || 0) / 100).toFixed(0);\\nconst items = r.items_json || [];\\nconst itemsText = items.map(it => `  • ${it.qty}x ${it.label} = ${(it.line_total/100).toFixed(0)} DA`).join('\\\\n');\\nconst trust = r.customer_trust_score || 50;\\nconst noshow = r.customer_no_show_count || 0;\\nconst riskEmoji = noshow > 0 ? '⚠️' : trust >= 70 ? '✅' : '⚡';\\n\\nconst reply = `*📦 Commande ${r.order_id?.toString().slice(0,8)}*\\n\\n*Status:* ${r.status} / ${r.payment_status}\\n*Mode:* ${r.payment_mode} | ${r.service_mode}\\n*Total:* ${total} DA\\n\\n*Articles:*\\n${itemsText || '(vide)'}\\n\\n*Client:* ${r.user_id}\\n${riskEmoji} Trust: ${trust}/100 | No-shows: ${noshow}\\n${r.delivery_address ? '*Adresse:* ' + r.delivery_address : ''}\\n\\n_Actions: !order noshow|cancel|delivered ${r.order_id?.toString().slice(0,8)}_`;\\nreturn [{json: {...$json, adminReplyText: reply}}];"},"id":"ORDER_SHOW_FORMAT","name":"E2b - Format Order","type":"n8n-nodes-base.code","typeVersion":2,"position":[520,1520]},{"parameters":{"conditions":{"string":[{"value1":"={{$json.adminAction}}","operation":"equal","value2":"ORDER_NOSHOW"}]}},"id":"ORDER_NOSHOW_CHECK","name":"E3 - Is ORDER_NOSHOW?","type":"n8n-nodes-base.if","typeVersion":2,"position":[120,1640]},{"parameters":{"operation":"executeQuery","query":"SELECT * FROM mark_order_noshow($1::uuid, $2);","additionalFields":{"queryParams":"={{[$json.adminOrderId, $json.userId]}}"}},"id":"ORDER_NOSHOW_DB","name":"E3a - Mark No-Show (DB)","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[320,1640]},{"parameters":{"language":"javascript","jsCode":"const r = ($json.data || [])[0];\\nif (!r || !r.success) {\\n  return [{json: {...$json, adminReplyText: '❌ Erreur: ' + (r?.message || 'Commande non trouvée')}}];\\n}\\nconst blacklistNote = r.blacklisted ? '\\\\n⛔ Client blacklisté (2+ no-shows)' : '';\\nconst re