W1 - IN WhatsApp Adapter (Secure + Fast ACK)	t	[{"parameters":{"httpMethod":"POST","path":"v1/inbound/whatsapp","responseMode":"responseNode","options":{"rawBody":true}},"id":"6b6bf307-4caa-4d32-8a17-27ffa1967f1b","name":"IN - Webhook","type":"n8n-nodes-base.webhook","typeVersion":1,"position":[-2400,0]},{"parameters":{"language":"javascript","jsCode":"const crypto = require('crypto');\\nconst fs = require('fs');\\nconst path = require('path');\\n\\n// =============================================================================\\n// P0-01: Parse Meta Native WhatsApp Payload\\n// Meta sends: { object: 'whatsapp_business_account', entry: [{ changes: [{ value: { messages: [...] } }] }] }\\n// =============================================================================\\nfunction extractAttachmentsWA(msg) {\\n  const attachments = [];\\n  const type = (msg.type || '').toString();\\n  \\n  if (type === 'image' && msg.image) {\\n    attachments.push({\\n      type: 'image',\\n      id: msg.image.id || '',\\n      mime: msg.image.mime_type || 'image/jpeg',\\n      sha256: msg.image.sha256 || '',\\n      url: '' // URL must be fetched via Graph API using media ID\\n    });\\n  }\\n  if (type === 'audio' && msg.audio) {\\n    attachments.push({\\n      type: 'audio',\\n      id: msg.audio.id || '',\\n      mime: msg.audio.mime_type || 'audio/ogg',\\n      sha256: msg.audio.sha256 || '',\\n      url: '' // URL must be fetched via Graph API using media ID\\n    });\\n  }\\n  if (type === 'video' && msg.video) {\\n    attachments.push({\\n      type: 'video',\\n      id: msg.video.id || '',\\n      mime: msg.video.mime_type || 'video/mp4',\\n      sha256: msg.video.sha256 || '',\\n      url: ''\\n    });\\n  }\\n  if (type === 'document' && msg.document) {\\n    attachments.push({\\n      type: 'document',\\n      id: msg.document.id || '',\\n      mime: msg.document.mime_type || 'application/pdf',\\n      filename: msg.document.filename || '',\\n      sha256: msg.document.sha256 || '',\\n      url: ''\\n    });\\n  }\\n  if (type === 'location' && msg.location) {\\n    attachments.push({\\n      type: 'location',\\n      latitude: msg.location.latitude,\\n      longitude: msg.location.longitude,\\n      name: msg.location.name || '',\\n      address: msg.location.address || ''\\n    });\\n  }\\n  if (type === 'sticker' && msg.sticker) {\\n    attachments.push({\\n      type: 'sticker',\\n      id: msg.sticker.id || '',\\n      mime: msg.sticker.mime_type || 'image/webp',\\n      animated: !!msg.sticker.animated\\n    });\\n  }\\n  if (type === 'contacts' && Array.isArray(msg.contacts)) {\\n    attachments.push({\\n      type: 'contacts',\\n      contacts: msg.contacts\\n    });\\n  }\\n  return attachments;\\n}\\n\\nfunction parseMetaNativeWA(rawBody) {\\n  // Check if this is Meta native format\\n  if (!rawBody || typeof rawBody !== 'object') return null;\\n  if (rawBody.object !== 'whatsapp_business_account') return null;\\n  \\n  const entry = rawBody.entry?.[0];\\n  if (!entry) return null;\\n  \\n  const change = entry.changes?.[0];\\n  if (!change) return null;\\n  \\n  const value = change.value;\\n  if (!value) return null;\\n  \\n  // P1-02: Ignore status updates (delivered, read, sent) - ACK 200 but no processing\\n  if (value.statuses && Array.isArray(value.statuses) && value.statuses.length > 0) {\\n    return { _isStatusUpdate: true, _ignore: true };\\n  }\\n  \\n  // Get first message (P1-01: multi-entry handled later)\\n  const msg = value.messages?.[0];\\n  if (!msg) return null;\\n  \\n  // Extract message text based on type\\n  let text = '';\\n  const msgType = (msg.type || 'text').toString();\\n  \\n  if (msgType === 'text') {\\n    text = msg.text?.body || '';\\n  } else if (msgType === 'interactive') {\\n    // Button reply or list reply\\n    if (msg.interactive?.type === 'button_reply') {\\n      text = msg.interactive.button_reply?.id || msg.interactive.button_reply?.title || '';\\n    } else if (msg.interactive?.type === 'list_reply') {\\n      text = msg.interactive.list_reply?.id || msg.interactive.list_reply?.title || '';\\n    }\\n  } else if (msgType === 'button') {\\n    // Quick reply button\\n    text = msg.button?.payload || msg.button?.text || '';\\n  }\\n  \\n  // Convert epoch timestamp to ISO 8601\\n  const epochTs = msg.timestamp;\\n  let isoTimestamp;\\n  if (epochTs) {\\n    const epochNum = Number(epochTs);\\n    // Meta sends seconds, not milliseconds\\n    const msTs = epochNum > 9999999999 ? epochNum : epochNum * 1000;\\n    isoTimestamp = new Date(msTs).toISOString();\\n  } else {\\n    isoTimestamp = new Date().toISOString();\\n  }\\n  \\n  // Extract metadata from value\\n  const metadata = value.metadata || {};\\n  const phoneNumberId = metadata.phone_number_id || '';\\n  const displayPhoneNumber = metadata.display_phone_number || '';\\n  \\n  return {\\n    _isMetaNative: true,\\n    provider: 'wa',\\n    msg_id: msg.id || '',\\n    from: msg.from || '',\\n    text: text,\\n    timestamp: isoTimestamp,\\n    type: msgType,\\n    attachments: extractAttachmentsWA(msg),\\n    meta: {\\n      phone_number_id: phoneNumberId,\\n      display_phone_number: displayPhoneNumber,\\n      wa_id: entry.id || '',\\n      original_type: msgType,\\n      context: msg.context || null // Reply context if any\\n    },\\n    raw_meta_message: msg\\n  };\\n}\\n\\n// =============================================================================\\n// Original code continues - body parsing\\n// =============================================================================\\nconst rawBodyInput = $json.body ?? $json;\\n\\n// P0-01: Try to parse as Meta native format first\\nconst metaNativeParsed = parseMetaNativeWA(rawBodyInput);\\n\\n// Determine the body to use for further processing\\nlet body;\\nlet isMetaNative = false;\\nlet isStatusUpdate = false;\\n\\nif (metaNativeParsed && metaNativeParsed._isStatusUpdate) {\\n  // Status update - we'll process but mark for sile