\n  // Dedupe disabled - always treat as new\\n  isNew = true;\\n} else if (redisResult && redisResult.error) {\\n  // Redis error - fallback to DB idempotency\\n  redisAvailable = false;\\n  redisError = redisResult.error.message || 'Redis GET error';\\n  isNew = true; // Assume new to not drop messages on Redis failure\\n} else if (redisResult === null || redisResult === undefined || redisResult === '' || (typeof redisResult === 'string' && redisResult.toLowerCase() === 'nil')) {\\n  // Key doesn't exist - NEW message\\n  isNew = true;\\n} else {\\n  // Key exists - DUPLICATE message\\n  isNew = false;\\n}\\n\\nreturn [{\\n  json: {\\n    ...input,\\n    _dedupe: {\\n      ...input._dedupe,\\n      isNew,\\n      isDuplicate: !isNew,\\n      redisAvailable,\\n      redisError,\\n      checkedAt: new Date().toISOString()\\n    }\\n  }\\n}];\\n"},"id":"dedupe-parse-wa","name":"B0 - Parse Dedupe Result","type":"n8n-nodes-base.code","typeVersion":2,"position":[100,-350]},{"parameters":{"conditions":{"boolean":[{"value1":"={{$json._dedupe.isNew}}","operation":"isTrue"}]}},"id":"dedupe-is-new-wa","name":"B0 - Is New (Redis)?","type":"n8n-nodes-base.if","typeVersion":2,"position":[350,-350]},{"parameters":{"operation":"set","key":"={{$json._dedupe.key}}","value":"={{$json._dedupe.checkedAt}}","expire":true,"ttl":"={{$json._dedupe.ttl}}"},"id":"dedupe-redis-set-wa","name":"B0 - Redis Dedupe SET","type":"n8n-nodes-base.redis","typeVersion":1,"position":[600,-450],"credentials":{"redis":{"id":"REDIS_CREDENTIAL_ID","name":"Redis"}},"continueOnFail":true},{"parameters":{"operation":"executeQuery","query":"WITH ins AS (\\n      INSERT INTO idempotency_keys (conversation_key, msg_id, channel)\\n      VALUES ($1, $2, $3)\\n      ON CONFLICT DO NOTHING\\n      RETURNING 1\\n    )\\n    SELECT COALESCE((SELECT 1 FROM ins), 0) AS inserted;","additionalFields":{"queryParams":"={{[$json.conversationKey, $json.metadata.msgId, $json.channel]}}"}},"id":"6a310cae-d2a9-46d3-9e16-da8f577f5