-ace1-4aab-9f4f-ae332a28b985","name":"B0 - RateLimit Flag","type":"n8n-nodes-base.code","typeVersion":2,"position":[550,-450]},{"parameters":{"conditions":{"boolean":[{"value1":"={{$json._sec.rateAllowed}}","operation":"isTrue"}]}},"id":"6609e416-2946-4521-b1e7-bda46a695942","name":"B0 - Rate OK?","type":"n8n-nodes-base.if","typeVersion":2,"position":[800,-450]},{"parameters":{"operation":"executeQuery","query":"SELECT 1 AS quarantined\\n    FROM conversation_quarantine\\n    WHERE conversation_key=$1 AND active=true\\n      AND (expires_at IS NULL OR expires_at > now())\\n    LIMIT 1;","additionalFields":{"queryParams":"={{[$json.conversationKey]}}"}},"id":"0437a2d3-aa7e-4f50-bbc0-632a8b300b53","name":"B0 - Quarantine Check","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[1050,-550]},{"parameters":{"language":"javascript","jsCode":"const q = ($json.quarantined === 1 || $json.quarantined === '1');\\nconst notQ = !q;\\nreturn [{json: {...$json, _sec: {...$json._sec, notQuarantined: notQ}}}];"},"id":"fb4efc11-e382-4ca4-951d-e0764859acd5","name":"B0 - Quarantine Flag","type":"n8n-nodes-base.code","typeVersion":2,"position":[1300,-550]},{"parameters":{"conditions":{"boolean":[{"value1":"={{$json._sec.notQuarantined}}","operation":"isTrue"}]}},"id":"ae5c99ae-3bc7-4b29-b278-d3bf8892aa05","name":"B0 - Not Quarantined?","type":"n8n-nodes-base.if","typeVersion":2,"position":[1550,-550]},{"parameters":{"language":"JavaScript","jsCode":"const crypto = require('crypto');\\nconst e = $json;\\nconst ctx = e.tenant_context || {};\\nconst seal = crypto.createHash('sha256').update(JSON.stringify(ctx)).digest('hex');\\nif (e.tenant_context_seal && seal !== e.tenant_context_seal) {\\n  throw new Error('TENANT_CONTEXT_TAMPERED');\\n}\\nreturn [{json:e}];\\n"},"id":"f87611bd-5bce-4a31-bf10-0c04b3e15d25","name":"B0 - Verify Tenant Context Seal","type":"n8n-nodes-base.code","typeVersion":2,"position":[1800,-650]},{"parameters":{"language":"javascript","jsCode":"/**\\n * P1-02: Queue media fetch requests for attachments with media_id\\n * Sends to ralphe:media:pending queue for W18_MEDIA_FETCH_WORKER to process\\n */\\nconst mediaFetchEnabled = (($env.MEDIA_FETCH_ENABLED || 'true').toString().toLowerCase() !== 'false');\\n\\nif (!mediaFetchEnabled) {\\n  return [{ json: { ...$json, _mediaQueue: { enabled: false, queued: 0 } } }];\\n}\\n\\n// Get attachments from envelope\\nconst envelope = $json.inbound_envelope || {};\\nconst atts = envelope.contract_version === 'v2'\\n  ? (Array.isArray(envelope.message?.attachments) ? envelope.message.attachments : [])\\n  : (Array.isArray(envelope.attachments) ? envelope.attachments : []);\\n\\n// Find attachments with media_id but no URL (need Graph API fetch)\\nconst mediaToFetch = atts.filter(a => {\\n  if (!a || !a.id) return false;\\n  // Only fetch if URL is empty or missing\\n  if (a.url && a.url.length > 0) return false;\\n  // Only media types that have Graph API URLs\\n  return ['image', 'audio', 'video', 'document', 'sticker'].includes(a.type);\\n});\\n\\nif (mediaToFetch.length === 0) {\\n  return [{ json: { ...$json, _mediaQueue: { enabled: true, queued: 0, attachments: [] } } }];\\n}\\n\\n// Prepare queue entries\\nconst queueEntries = mediaToFetch.map(a => ({\\n  media_id: a.id,\\n  media_type: a.type,\\n  mime: a.mime || '',\\n  sha256: a.sha256 || '',\\n  msg_id: $json.metadata?.msgId || '',\\n  correlation_id: $json._timing?.correlation_id || '',\\n  channel: 'whatsapp',\\n  user_id: $json.userId || '',\\n  conversation_key: $json.conversationKey || '',\\n  queued_at: new Date().toISOString(),\\n  attempts: 0\\n}));\\n\\nreturn [{\\n  json: {\\n    ...$json,\\n    _mediaQueue: {\\n      enabled: true,\\n      queued: queueEntries.length,\\n      entries: queueEntries\\n    }\\n  }\\n}];\\n"},"id":"media-queue-prepare","name":"B1 - Prepare Media Queue","type":"n8n-nodes-base.code","typeVersion":2,"position":[2050,-650]},{"parameters":{"conditions":{"number":[{"value1":"={{$json._medi