Insert","type":"n8n-nodes-base.postgres","typeVersion":2,"position":[1300,-350]},{"parameters":{"language":"javascript","jsCode":"/**\\n * P1-04: Prepare anti-replay key based on payload hash\\n * Hash = sha256(channel + msg_id + from + text_hash)\\n */\\nconst crypto = require('crypto');\\nconst replayEnabled = (($env.REPLAY_GUARD_ENABLED || 'true').toString().toLowerCase() !== 'false');\\nconst replayTtl = parseInt($env.META_REPLAY_WINDOW_SEC || $env.REPLAY_WINDOW_SECONDS || '300', 10);\\nconst replayMode = ($env.REPLAY_GUARD_MODE || 'warn').toString().toLowerCase(); // warn|enforce\\n\\nconst channel = $json.channel || 'whatsapp';\\nconst msgId = $json.metadata?.msgId || '';\\nconst userId = $json.userId || '';\\nconst textHash = $json._sec?.textHash || '';\\n\\n// Create payload hash for replay detection\\nconst payloadStr = `${channel}:${msgId}:${userId}:${textHash}`;\\nconst payloadHash = crypto.createHash('sha256').update(payloadStr).digest('hex').substring(0, 16);\\nconst replayKey = `ralphe:replay:${channel}:${payloadHash}`;\\n\\nreturn [{\\n  json: {\\n    ...$json,\\n    _replay: {\\n      enabled: replayEnabled,\\n      key: replayKey,\\n      ttl: replayTtl,\\n      mode: replayMode,\\n      payloadHash\\n    }\\n  }\\n}];\\n"},"id":"replay-prepare-wa","name":"B0 - Prepare Replay Key","type":"n8n-nodes-base.code","typeVersion":2,"position":[-1350,-300]},{"parameters":{"operation":"get","key":"={{$json._replay.key}}"},"id":"replay-redis-get-wa","name":"B0 - Replay Check GET","type":"n8n-nodes-base.redis","typeVersion":1,"position":[-1150,-300],"credentials":{"redis":{"id":"REDIS_CREDENTIAL_ID","name":"Redis"}},"continueOnFail":true},{"parameters":{"language":"javascript","jsCode":"/**\\n * P1-04: Parse replay check result\\n */\\nconst input = $('B0 - Prepare Replay Key').first().json;\\nconst redisResult = $json;\\nconst replayEnabled = input._replay?.enabled !== false;\\nconst replayMode = input._replay?.mode || 'warn';\\n\\nlet isReplay = false;\\nlet redisAvailable = true;\\nlet redisError = null;\\n\\nif (!replayEnabled) {\\n  isReplay = false;\\n} else if (redisResult && redisResult.error) {\\n  redisAvailable = false;\\n  redisError = redisResult.error.message || 'Redis GET error';\\n  isReplay = false; // Fail-open if Redis unavailable\\n} else if (redisResult === null || redisResult === undefined || redisResult === '' || (typeof redisResult === 'string' && redisResult.toLowerCase() === 'nil')) {\\n  isReplay = false; // Key not found = new message\\n} else {\\n  isReplay = true; // Key exists = replay detected\\n}\\n\\nreturn [{\\n  json: {\\n    ...input,\\n    _replay: {\\n      ...input._replay,\\n      isReplay,\\n      isNew: !isReplay,\\n      redisAvailable,\\n      redisError,\\n      shouldBlock: isReplay && replayMode === 'enforce',\\n      checkedAt: new Date().toISOString()\\n    }\\n  }\\n}];\\n"},"id":"replay-parse-wa","name":"B0 - Parse Replay Result","type":"n8n-nodes-base.code","typeVersion":2,"position":[-950,-300]},{"parameters":{"conditions":{"boolean":[{"value1":"={{$json._replay.isNew || !$json._replay.enabled}}","operation":"isTrue"}]}},"id":"replay-is-new-wa","name":"B0 - Is New (Replay)?","type":"n8n-nodes-base.if","typeVersion":2,"position":[-750,-300]},{"parameters":{"operation":"set","key":"={{$json._replay.key}}","value":"={{$json._replay.checkedAt}}","expire":true,"ttl":"={{$json._replay.ttl}}"},"id":"replay-redis-set-wa","name":"B0 - Replay SET","type":"n8n-nodes-base.redis","typeVersion":1,"position":[-550,-400],"credentials":{"redis":{"id":"REDIS_CREDENTIAL_ID","name":"Redis"}},"continueOnFail":true},{"parameters":{"language":"javascript","jsCode":"/**\\n * P1-04: Replay detected - log and stop\\n */\\nconst input = $json;\\nconst shouldBlock = input._replay?.shouldBlock || false;\\nconst mode = input._replay?.mode || 'warn';\\n\\n// Log replay detection\\nconsole.log(`[P1-04] Replay detected: key=${input._replay?.key}, mode=${mode}, block=${shouldBlock}`);\\n\\nreturn [{\\