W_DRIVER_ACTIONS	t	[{"parameters":{"httpMethod":"POST","path":"driver/action","options":{}},"name":"Driver Action","type":"n8n-nodes-base.webhook","typeVersion":1,"position":[100,300],"id":"45887add-8c8a-496a-895c-d643a6a34f0c"},{"parameters":{"jsCode":"const input = $input.first().json;\\nconst phone = (input.from || input.phone || '').toString().trim();\\nconst buttonId = (input.button_id || input.interactive?.button_reply?.id || '').toString().trim();\\nconst text = (input.text || input.message?.text || '').toString().trim();\\n\\nlet action = 'unknown';\\nlet orderId = null;\\nlet targetPhone = null;\\n\\nif (buttonId.startsWith('CLAIM_')) {\\n  action = 'claim';\\n  orderId = buttonId.replace('CLAIM_', '');\\n} else if (buttonId.startsWith('IGNORE_')) {\\n  action = 'ignore';\\n  orderId = buttonId.replace('IGNORE_', '');\\n} else if (buttonId.startsWith('DELIVERED_')) {\\n  action = 'delivered_prompt';\\n  orderId = buttonId.replace('DELIVERED_', '');\\n} else if (buttonId === 'REFRESH_AVAILABLE') {\\n  action = 'refresh';\\n} else if (buttonId === 'MENU') {\\n  action = 'menu';\\n} else if (buttonId.startsWith('CALL_')) {\\n  action = 'call';\\n  targetPhone = buttonId.replace('CALL_', '');\\n} else if (/^\\\\d{4}$/.test(text)) {\\n  action = 'otp_verify';\\n}\\n\\nreturn { json: { phone, buttonId, text, action, orderId, targetPhone } };"},"name":"Parse Action","type":"n8n-nodes-base.code","typeVersion":1,"position":[300,300],"id":"a8f34429-cac8-4bc6-bf71-95c464815bdf"},{"parameters":{"rules":{"values":[{"conditions":{"conditions":[{"leftValue":"={{ $json.action }}","rightValue":"claim","operator":{"type":"string","operation":"equals"}}]},"renameOutput":"Claim"},{"conditions":{"conditions":[{"leftValue":"={{ $json.action }}","rightValue":"ignore","operator":{"type":"string","operation":"equals"}}]},"renameOutput":"Ignore"},{"conditions":{"conditions":[{"leftValue":"={{ $json.action }}","rightValue":"delivered_prompt","operator":{"type":"string","operation":"e