, 10);\\nconst otpExpiresAt = new Date(Date.now() + expiryMinutes * 60000).toISOString();\\n\\nreturn {\\n  json: {\\n    ...($json),\\n    otp,\\n    otpHash,\\n    otpExpiresAt\\n  }\\n};"},"name":"Generate & Hash OTP","type":"n8n-nodes-base.code","typeVersion":1,"position":[1300,0],"id":"9adeb230-4dd2-433e-a51b-d1f66ed61870"},{"parameters":{"url":"={{ $env.STRAPI_URL || 'http://inventory-cms:1337' }}/api/drivers?filters[phone_number][$eq]={{ $json.phone }}&filters[is_active][$eq]=true","method":"GET","headerParameters":{"parameters":[{"name":"Authorization","value":"Bearer {{ $env.STRAPI_API_TOKEN }}"}]}},"name":"Get Driver for Claim","type":"n8n-nodes-base.httpRequest","typeVersion":3,"position":[1500,0],"id":"c4569a48-be7e-4c15-a2c4-8fbe3ee38647"},{"parameters":{"jsCode":"const driver = ($json.data || [])[0];\\nconst attr = driver?.attributes || driver || {};\\nconst driverId = driver?.id;\\nconst prevData = $node['Generate & Hash OTP'].json;\\n\\nconst needsActivation = attr.onboarding_status === 'INVITED';\\n\\nreturn {\\n  json: {\\n    ...prevData,\\n    driverId,\\n    needsActivation\\n  }\\n};"},"name":"Prepare Claim Data","type":"n8n-nodes-base.code","typeVersion":1,"position":[1700,0],"id":"683c43ca-2900-423d-ac99-d071844afe61"},{"parameters":{"url":"={{ $env.STRAPI_URL || 'http://inventory-cms:1337' }}/api/orders/{{ $json.orderId }}","method":"PUT","sendBody":true,"bodyParameters":{"parameters":[{"name":"data","value":"={{ { delivery_status: 'OUT_FOR_DELIVERY', driver: $json.driverId, otp_hash: $json.otpHash, otp_expires_at: $json.otpExpiresAt, otp_attempts: 0 } }}"}]},"headerParameters":{"parameters":[{"name":"Authorization","value":"Bearer {{ $env.STRAPI_API_TOKEN }}"}]}},"name":"Assign Order to Driver","type":"n8n-nodes-base.httpRequest","typeVersion":3,"position":[1900,0],"id":"29047b95-fbd5-4a71-9abd-af7fb64a50e0"},{"parameters":{"jsCode":"const d = $node['Prepare Claim Data'].json;\\nconst address = [d.deliveryAddress, d.deliveryCommune, d.deliveryWilaya].filter(Boolean).join(', ');\\nconst mapsUrl = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(address)}`;\\n\\n// Activate driver if first delivery\\nconst activateDriver = d.needsActivation;\\n\\nreturn {\\n  json: {\\n    phone: d.phone,\\n    customerPhone: d.customerPhone,\\n    otp: d.otp,\\n    orderId: d.orderId,\\n    driverId: d.driverId,\\n    activateDriver,\\n    totalAmount: d.totalAmount,\\n    address,\\n    mapsUrl,\\n    customerMessage: `🛵 *Bonne nouvelle !*\\\\n\\\\nVotre commande est en route !\\\\n\\\\n📍 Livreur en chemin...\\\\n\\\\n🔐 *Code de vérification* : *${d.otp}*\\\\n\\\\nDonnez ce code au livreur à la réception.`,\\n    driverMessage: `✅ *Commande acceptée !*\\\\n\\\\n📍 *Adresse* : ${address}\\\\n\\\\n🗺️ Itinéraire : ${mapsUrl}\\\\n\\\\n📞 Client : ${d.customerPhone}\\\\n\\\\nBonne route ! 🚀`\\n  }\\n};"},"name":"Build Claim Messages","type":"n8n-nodes-base.code","typeVersion":1,"position":[2100,0],"id":"82505e91-3b7d-4eb2-8f65-0206772f7dd7"},{"parameters":{"url":"={{ $env.WA_SEND_URL || `https://graph.facebook.com/${$env.GRAPH_API_VERSION || 'v21.0'}/${$env.WA_PHONE_NUMBER_ID}/messages` }}","method":"POST","sendBody":true,"bodyParameters":{"parameters":[{"name":"messaging_product","value":"whatsapp"},{"name":"to","value":"={{ $json.customerPhone }}"},{"name":"type","value":"text"},{"name":"text","value":"={{ { body: $json.customerMessage } }}"}]},"headerParameters":{"parameters":[{"name":"Authorization","value":"Bearer {{ $env.WA_API_TOKEN }}"}]}},"name":"Send OTP to Customer","type":"n8n-nodes-base.httpRequest","typeVersion":3,"position":[2300,-100],"id":"e11ca92e-579d-4950-8e7d-0e05625a0550"},{"parameters":{"url":"={{ $env.WA_SEND_URL || `https://graph.facebook.com/${$env.GRAPH_API_VERSION || 'v21.0'}/${$env.WA_PHONE_NUMBER_ID}/messages` }}","method":"POST","sendBody":true,"bodyParameters":{"parameters":[{"name":"messaging_product","value":"whatsapp"},{"name":"to","value":"={{ $json.phone }}"},{"name":