W_DRIVER_OTP_VERIFY	t	[{"parameters":{"httpMethod":"POST","path":"driver/otp-verify","options":{}},"name":"OTP Input","type":"n8n-nodes-base.webhook","typeVersion":1,"position":[100,300],"id":"64598cc8-1461-4d03-91c6-b6cc102a8962"},{"parameters":{"jsCode":"const input = $input.first().json;\\nconst phone = (input.from || input.phone || '').toString().trim();\\nconst text = (input.text || input.message?.text || '').toString().trim();\\n\\nconst isOtp = /^\\\\d{4}$/.test(text);\\n\\nreturn { json: { phone, otp: text, isOtp } };"},"name":"Parse OTP","type":"n8n-nodes-base.code","typeVersion":1,"position":[300,300],"id":"cbe2b6fa-9e95-4593-8c5d-0fa66c0417c4"},{"parameters":{"conditions":{"boolean":[{"value1":"={{ $json.isOtp }}","operation":"equal","value2":true}]}},"name":"Is Valid OTP Format?","type":"n8n-nodes-base.if","typeVersion":1,"position":[500,300],"id":"06f415b5-129e-4e6e-ab12-673ff4c958a6"},{"parameters":{"url":"={{ $env.STRAPI_URL || 'http://inventory-cms:1337' }}/api/orders?filters[driver][phone_number][$eq]={{ $json.phone }}&filters[delivery_status][$eq]=OUT_FOR_DELIVERY&pagination[limit]=1&populate=driver","method":"GET","headerParameters":{"parameters":[{"name":"Authorization","value":"Bearer {{ $env.STRAPI_API_TOKEN }}"}]}},"name":"Fetch Active Order","type":"n8n-nodes-base.httpRequest","typeVersion":3,"position":[700,200],"id":"43f0f00c-a28b-457b-aab3-6e6204ae68d8"},{"parameters":{"conditions":{"number":[{"value1":"={{ ($json.data || []).length }}","operation":"larger","value2":0}]}},"name":"Has Active Order?","type":"n8n-nodes-base.if","typeVersion":1,"position":[900,200],"id":"87bad0b2-4ae4-40e3-92d7-e235e2f04259"},{"parameters":{"jsCode":"const crypto = require('crypto');\\n\\nconst order = $json.data[0];\\nconst attr = order.attributes || order;\\nconst orderId = order.id;\\nconst phone = $node['Parse OTP'].json.phone;\\nconst inputOtp = $node['Parse OTP'].json.otp;\\n\\nconst maxAttempts = parseInt($env.DRIVER_OTP_MAX_ATTEMPTS || '3', 10);\\nconst currentAttempts = attr.otp_attempts || 0;\\nconst otpHash = attr.otp_hash || '';\\nconst otpExpiresAt = attr.otp_expires_at ? new Date(attr.otp_expires_at) : null;\\nconst totalAmount = attr.total_amount || 0;\\nconst driverId = attr.driver?.data?.id || attr.driver?.id || null;\\n\\n// Check attempts exceeded\\nif (currentAttempts >= maxAttempts) {\\n  return { json: { phone, orderId, status: 'BLOCKED', message: '🔒 *Code bloqué*\\\\n\\\\nTrop de tentatives. Contactez le support.' } };\\n}\\n\\n// Check expiry\\nif (otpExpiresAt && otpExpiresAt < new Date()) {\\n  return { json: { phone, orderId, status: 'EXPIRED', message: '⏰ *Code expiré*\\\\n\\\\nLe code OTP a expiré. Demandez un nouveau code au support.' } };\\n}\\n\\n// Hash input and compare\\nconst inputHash = crypto.createHash('sha256').update(inputOtp).digest('hex');\\n\\nif (inputHash !== otpHash) {\\n  const newAttempts = currentAttempts + 1;\\n  const remaining = maxAttempts - newAttempts;\\n  return {\\n    json: {\\n      phone,\\n      orderId,\\n      status: 'MISMATCH',\\n      newAttempts,\\n      message: `❌ *Code incorrect*\\\\n\\\\nTentative ${newAttempts}/${maxAttempts}.${remaining > 0 ? ` Il vous reste ${remaining} essai(s).` : ' Code bloqué.'}`\\n    }\\n  };\\n}\\n\\n// OTP matches!\\nreturn {\\n  json: {\\n    phone,\\n    orderId,\\n    driverId,\\n    totalAmount,\\n    status: 'MATCH'\\n  }\\n};"},"name":"Verify OTP Hash","type":"n8n-nodes-base.code","typeVersion":1,"position":[1100,100],"id":"83a024f3-b7dc-4dbd-a72c-fb2f5293ef3b"},{"parameters":{"rules":{"values":[{"conditions":{"conditions":[{"leftValue":"={{ $json.status }}","rightValue":"MATCH","operator":{"type":"string","operation":"equals"}}]},"renameOutput":"Match"},{"conditions":{"conditions":[{"leftValue":"={{ $json.status }}","rightValue":"MISMATCH","operator":{"type":"string","operation":"equals"}}]},"renameOutput":"Mismatch"}],"fallbackOutput":"extra"},"options":{}},"name":"OTP Result","type":"n8n-nodes-base.switch","typeVe